//
// Mixins: Miscellaneous
//

// ETC
@mixin translate($x, $y) {
  transform: translate($x, $y) !important ;
}

// Different radius each side
@mixin border-radius-sides($top-left, $top-right, $bottom-left, $bottom-right) {
  border-radius: $top-left $top-right $bottom-left $bottom-right !important ;
}

@mixin calc($property, $expression) {
  #{$property}: calc(#{$expression}) !important ;
}

@mixin rotate($value) {
  transform: rotate($value) !important ;
}

@mixin animation($animation) {
  animation: $animation !important ;
}

// Gradient background
@mixin gradient($color: #f5f5f5, $start: #eee, $stop: $white) {
  background-color: $color !important ;
  background-image: gradient(linear, left bottom, left top, color-stop(0, $start), color-stop(1, $stop)) !important ;
}

