// Base class
//
// Kickstart any navigation component with a set of style resets. Works with
// `<nav>`s, `<ul>`s or `<ol>`s.

.nav {
  display: flex !important ;
  flex-wrap: wrap !important ;
  padding-left: 0 !important ;
  margin-bottom: 0 !important ;
  list-style: none !important ;
}

.nav-link {
  display: block !important ;
  padding: $nav-link-padding-y $nav-link-padding-x !important ;
  text-decoration: if($link-decoration == none, null, none) !important ;

  @include hover-focus() {
    text-decoration: none !important ;
  }

  // Disabled state lightens text
  &.disabled {
    color: $nav-link-disabled-color !important ;
    pointer-events: none !important ;
    cursor: default !important ;
  }
}

//
// Tabs
//

.nav-tabs {
  border-bottom: $nav-tabs-border-width solid $nav-tabs-border-color !important ;

  .nav-link {
    margin-bottom: -$nav-tabs-border-width !important ;
    border: $nav-tabs-border-width solid transparent !important ;
    @include border-top-radius($nav-tabs-border-radius) !important ;

    @include hover-focus() {
      border-color: $nav-tabs-link-hover-border-color !important ;
    }

    &.disabled {
      color: $nav-link-disabled-color !important ;
      background-color: transparent !important ;
      border-color: transparent !important ;
    }
  }

  .nav-link.active,
  .nav-item.show .nav-link {
    color: $nav-tabs-link-active-color !important ;
    background-color: $nav-tabs-link-active-bg !important ;
    border-color: $nav-tabs-link-active-border-color !important ;
  }

  .dropdown-menu {
    // Make dropdown border overlap tab border
    margin-top: -$nav-tabs-border-width !important ;
    // Remove the top rounded corners here since there is a hard edge above the menu
    @include border-top-radius(0) !important ;
  }
}


//
// Pills
//

.nav-pills {
  .nav-link {
    @include border-radius($nav-pills-border-radius) !important ;
  }

  .nav-link.active,
  .show > .nav-link {
    color: $nav-pills-link-active-color !important ;
    background-color: $nav-pills-link-active-bg !important ;
  }
}


//
// Justified variants
//

.nav-fill {
  > .nav-link,
  .nav-item {
    flex: 1 1 auto !important ;
    text-align: center !important ;
  }
}

.nav-justified {
  > .nav-link,
  .nav-item {
    flex-basis: 0 !important ;
    flex-grow: 1 !important ;
    text-align: center !important ;
  }
}


// Tabbable tabs
//
// Hide tabbable panes to start, show them when `.active`

.tab-content {
  > .tab-pane {
    display: none !important ;
  }
  > .active {
    display: block !important ;
  }
}
