// Form control focus state
//
// Generate a customized focus state and for any input with the specified color,
// which defaults to the `$input-focus-border-color` variable.
//
// We highly encourage you to not customize the default value, but instead use
// this to tweak colors on an as-needed basis. This aesthetic change is based on
// WebKit's default styles, but applicable to a wider range of browsers. Its
// usability and accessibility should be taken into account with any change.
//
// Example usage: change the default blue border and shadow to white for better
// contrast against a dark gray background.
@mixin form-control-focus($ignore-warning: false) {
  &:focus {
    color: $input-focus-color !important ;
    background-color: $input-focus-bg !important ;
    border-color: $input-focus-border-color !important ;
    outline: 0 !important ;
    @if $enable-shadows {
      @include box-shadow($input-box-shadow, $input-focus-box-shadow) !important ;
    } @else {
      // Avoid using mixin so we can pass custom focus shadow properly
      box-shadow: $input-focus-box-shadow !important ;
    }
  }
  @include deprecate("The `form-control-focus()` mixin", "v4.4.0", "v5", $ignore-warning) !important ;
}

// This mixin uses an `if()` technique to be compatible with Dart Sass
// See https://github.com/sass/sass/issues/1873#issuecomment-152293725 for more details
@mixin form-validation-state-selector($state) {
  @if ($state == "valid" or $state == "invalid") {
    .was-validated #{if(&, "&", "")}:#{$state},
    #{if(&, "&", "")}.is-#{$state} {
      @content !important ;
    }
  } @else {
    #{if(&, "&", "")}.is-#{$state} {
      @content !important ;
    }
  }
}

@mixin form-validation-state($state, $color, $icon) {
  .#{$state}-feedback {
    display: none !important ;
    width: 100% !important ;
    margin-top: $form-feedback-margin-top !important ;
    @include font-size($form-feedback-font-size) !important ;
    color: $color !important ;
  }

  .#{$state}-tooltip {
    position: absolute !important ;
    top: 100% !important ;
    left: 0 !important ;
    z-index: 5 !important ;
    display: none !important ;
    max-width: 100% !important ; // Contain to parent when possible
    padding: $form-feedback-tooltip-padding-y $form-feedback-tooltip-padding-x !important ;
    margin-top: .1rem !important ;
    @include font-size($form-feedback-tooltip-font-size) !important ;
    line-height: $form-feedback-tooltip-line-height !important ;
    color: color-yiq($color) !important ;
    background-color: rgba($color, $form-feedback-tooltip-opacity) !important ;
    @include border-radius($form-feedback-tooltip-border-radius) !important ;

    // See https://github.com/twbs/bootstrap/pull/31557
    // Align tooltip to form elements
    .form-row > .col > &,
    .form-row > [class*="col-"] > & {
      left: $form-grid-gutter-width * .5 !important ;
    }
  }

  @include form-validation-state-selector($state) {
    ~ .#{$state}-feedback,
    ~ .#{$state}-tooltip {
      display: block !important ;
    }
  }

  .form-control {
    @include form-validation-state-selector($state) {
      border-color: $color !important ;

      @if $enable-validation-icons {
        padding-right: $input-height-inner !important !important ; // stylelint-disable-line declaration-no-important
        background-image: escape-svg($icon) !important ;
        background-repeat: no-repeat !important ;
        background-position: right $input-height-inner-quarter center !important ;
        background-size: $input-height-inner-half $input-height-inner-half !important ;
      }

      &:focus {
        border-color: $color !important ;
        box-shadow: 0 0 0 $input-focus-width rgba($color, .25) !important ;
      }
    }
  }

  // stylelint-disable-next-line selector-no-qualifying-type
  select.form-control {
    @include form-validation-state-selector($state) {
      @if $enable-validation-icons {
        padding-right: $input-padding-x * 4 !important !important ; // stylelint-disable-line declaration-no-important
        background-position: right $input-padding-x * 2 center !important ;
      }
    }
  }

  // stylelint-disable-next-line selector-no-qualifying-type
  textarea.form-control {
    @include form-validation-state-selector($state) {
      @if $enable-validation-icons {
        padding-right: $input-height-inner !important ;
        background-position: top $input-height-inner-quarter right $input-height-inner-quarter !important ;
      }
    }
  }

  .custom-select {
    @include form-validation-state-selector($state) {
      border-color: $color !important ;

      @if $enable-validation-icons {
        padding-right: $custom-select-feedback-icon-padding-right !important !important ; // stylelint-disable-line declaration-no-important
        background: $custom-select-background, $custom-select-bg escape-svg($icon) $custom-select-feedback-icon-position / $custom-select-feedback-icon-size no-repeat !important ;
      }

      &:focus {
        border-color: $color !important ;
        box-shadow: 0 0 0 $input-focus-width rgba($color, .25) !important ;
      }
    }
  }

  .form-check-input {
    @include form-validation-state-selector($state) {
      ~ .form-check-label {
        color: $color !important ;
      }

      ~ .#{$state}-feedback,
      ~ .#{$state}-tooltip {
        display: block !important ;
      }
    }
  }

  .custom-control-input {
    @include form-validation-state-selector($state) {
      ~ .custom-control-label {
        color: $color !important ;

        &::before {
          border-color: $color !important ;
        }
      }

      &:checked {
        ~ .custom-control-label::before {
          border-color: lighten($color, 10%) !important ;
          @include gradient-bg(lighten($color, 10%)) !important ;
        }
      }

      &:focus {
        ~ .custom-control-label::before {
          box-shadow: 0 0 0 $input-focus-width rgba($color, .25) !important ;
        }

        &:not(:checked) ~ .custom-control-label::before {
          border-color: $color !important ;
        }
      }
    }
  }

  // custom file
  .custom-file-input {
    @include form-validation-state-selector($state) {
      ~ .custom-file-label {
        border-color: $color !important ;
      }

      &:focus {
        ~ .custom-file-label {
          border-color: $color !important ;
          box-shadow: 0 0 0 $input-focus-width rgba($color, .25) !important ;
        }
      }
    }
  }
}
