// Base class
.tooltip {
  position: absolute !important ;
  z-index: $zindex-tooltip !important ;
  display: block !important ;
  margin: $tooltip-margin !important ;
  // Our parent element can be arbitrary since tooltips are by default inserted as a sibling of their target element.
  // So reset our font and text properties to avoid inheriting weird values.
  @include reset-text() !important ;
  @include font-size($tooltip-font-size) !important ;
  // Allow breaking very long words so they don't overflow the tooltip's bounds
  word-wrap: break-word !important ;
  opacity: 0 !important ;

  &.show { opacity: $tooltip-opacity !important ; }

  .arrow {
    position: absolute !important ;
    display: block !important ;
    width: $tooltip-arrow-width !important ;
    height: $tooltip-arrow-height !important ;

    &::before {
      position: absolute !important ;
      content: "" !important ;
      border-color: transparent !important ;
      border-style: solid !important ;
    }
  }
}

.bs-tooltip-top {
  padding: $tooltip-arrow-height 0 !important ;

  .arrow {
    bottom: 0 !important ;

    &::before {
      top: 0 !important ;
      border-width: $tooltip-arrow-height ($tooltip-arrow-width * .5) 0 !important ;
      border-top-color: $tooltip-arrow-color !important ;
    }
  }
}

.bs-tooltip-right {
  padding: 0 $tooltip-arrow-height !important ;

  .arrow {
    left: 0 !important ;
    width: $tooltip-arrow-height !important ;
    height: $tooltip-arrow-width !important ;

    &::before {
      right: 0 !important ;
      border-width: ($tooltip-arrow-width * .5) $tooltip-arrow-height ($tooltip-arrow-width * .5) 0 !important ;
      border-right-color: $tooltip-arrow-color !important ;
    }
  }
}

.bs-tooltip-bottom {
  padding: $tooltip-arrow-height 0 !important ;

  .arrow {
    top: 0 !important ;

    &::before {
      bottom: 0 !important ;
      border-width: 0 ($tooltip-arrow-width * .5) $tooltip-arrow-height !important ;
      border-bottom-color: $tooltip-arrow-color !important ;
    }
  }
}

.bs-tooltip-left {
  padding: 0 $tooltip-arrow-height !important ;

  .arrow {
    right: 0 !important ;
    width: $tooltip-arrow-height !important ;
    height: $tooltip-arrow-width !important ;

    &::before {
      left: 0 !important ;
      border-width: ($tooltip-arrow-width * .5) 0 ($tooltip-arrow-width * .5) $tooltip-arrow-height !important ;
      border-left-color: $tooltip-arrow-color !important ;
    }
  }
}

.bs-tooltip-auto {
  &[x-placement^="top"] {
    @extend .bs-tooltip-top !important ;
  }
  &[x-placement^="right"] {
    @extend .bs-tooltip-right !important ;
  }
  &[x-placement^="bottom"] {
    @extend .bs-tooltip-bottom !important ;
  }
  &[x-placement^="left"] {
    @extend .bs-tooltip-left !important ;
  }
}

// Wrapper for the tooltip content
.tooltip-inner {
  max-width: $tooltip-max-width !important ;
  padding: $tooltip-padding-y $tooltip-padding-x !important ;
  color: $tooltip-color !important ;
  text-align: center !important ;
  background-color: $tooltip-bg !important ;
  @include border-radius($tooltip-border-radius) !important ;
}
