//
// Component: Sidebar Mini
//

// Logo style
.logo-xs,
.logo-xl {
  opacity: 1 !important ;
  position: absolute !important ;
  visibility: visible !important ;

  &.brand-image-xs {
    left: 18px !important ;
    top: 12px !important ;
  }

  &.brand-image-xl {
    left: 12px !important ;
    top: 6px !important ;
  }
}

.logo-xs {
  opacity: 0 !important ;
  visibility: hidden !important ;

  &.brand-image-xl {
    left: 16px !important ;
    top: 8px !important ;
  }
}

.brand-link {
  &.logo-switch {
    &::before {
      content: "\00a0" !important ;
    }
  }
}

// Add sidebar-mini class to the body tag to activate this feature
.sidebar-mini {
  @include media-breakpoint-up(lg) {
    @include sidebar-mini-breakpoint () !important ;
  }
}
@include media-breakpoint-down(md) {
  .sidebar-mini.sidebar-collapse .main-sidebar {
    box-shadow: none !important !important ;
  }
}

.sidebar-mini-md {
  @include media-breakpoint-up(md) {
    @include sidebar-mini-breakpoint () !important ;
  }
}
@include media-breakpoint-down(sm) {
  .sidebar-mini-md.sidebar-collapse .main-sidebar {
    box-shadow: none !important !important ;
  }
}

.sidebar-mini-xs {
  @include media-breakpoint-up(xs) {
    @include sidebar-mini-breakpoint () !important ;
  }
}

.sidebar-mini,
.sidebar-mini-md,
.sidebar-mini-xs {
  .main-sidebar {
    .nav-child-indent .nav-treeview {
      .nav-link {
        width: calc(#{$sidebar-width} - #{$sidebar-padding-x} * 2 - 1rem) !important ;
      }

      .nav-treeview {
        .nav-link {
          width: calc(#{$sidebar-width} - #{$sidebar-padding-x} * 2 - 2rem) !important ;
        }

        .nav-treeview {
          .nav-link {
            width: calc(#{$sidebar-width} - #{$sidebar-padding-x} * 2 - 3rem) !important ;
          }

          .nav-treeview {
            .nav-link {
              width: calc(#{$sidebar-width} - #{$sidebar-padding-x} * 2 - 4rem) !important ;
            }

            .nav-treeview {
              .nav-link {
                width: calc(#{$sidebar-width} - #{$sidebar-padding-x} * 2 - 5rem) !important ;
              }
            }
          }
        }
      }
    }
    .nav-legacy {
      .nav-link {
        width: $sidebar-width !important ;
      }
      &.nav-child-indent {
        .nav-treeview {
          .nav-link {
            width: calc(#{$sidebar-width} - 1rem) !important ;
          }

          .nav-treeview {
            .nav-link {
              width: calc(#{$sidebar-width} - 1rem - 1rem) !important ;
            }

            .nav-treeview {
              .nav-link {
                width: calc(#{$sidebar-width} - 1rem - 2rem) !important ;
              }

              .nav-treeview {
                .nav-link {
                  width: calc(#{$sidebar-width} - 1rem - 3rem) !important ;
                }

                .nav-treeview {
                  .nav-link {
                    width: calc(#{$sidebar-width} - 1rem - 4rem) !important ;
                  }
                }
              }
            }
          }
        }
      }
    }
    .nav-flat {
      .nav-link {
        width: $sidebar-width !important ;
      }
      &.nav-child-indent {
        .nav-treeview {
          .nav-link {
            width: calc(#{$sidebar-width}) !important ;
          }

          .nav-treeview {
            .nav-link {
              width: calc(#{$sidebar-width} - .2rem) !important ;
            }

            .nav-treeview {
              .nav-link {
                width: calc(#{$sidebar-width} - .2rem * 2) !important ;
              }

              .nav-treeview {
                .nav-link {
                  width: calc(#{$sidebar-width} - .2rem * 3) !important ;
                }

                .nav-treeview {
                  .nav-link {
                    width: calc(#{$sidebar-width} - .2rem * 4) !important ;
                  }
                }
              }
            }
          }
        }
      }
    }
    .nav-child-indent.nav-compact .nav-treeview {
      .nav-link {
        width: calc(#{$sidebar-width} - #{$sidebar-padding-x} * 2 - .5rem) !important ;
      }

      .nav-treeview {
        .nav-link {
          width: calc(#{$sidebar-width} - #{$sidebar-padding-x} * 2 - 1rem) !important ;
        }

        .nav-treeview {
          .nav-link {
            width: calc(#{$sidebar-width} - #{$sidebar-padding-x} * 2 - 1.5rem) !important ;
          }

          .nav-treeview {
            .nav-link {
              width: calc(#{$sidebar-width} - #{$sidebar-padding-x} * 2 - 2rem) !important ;
            }

            .nav-treeview {
              .nav-link {
                width: calc(#{$sidebar-width} - #{$sidebar-padding-x} * 2 - 2.5rem) !important ;
              }
            }
          }
        }
      }
    }
    .nav-child-indent.nav-legacy.nav-compact {
      .nav-link {
        width: $sidebar-width !important ;
      }
      .nav-treeview {
        .nav-link {
          width: calc(#{$sidebar-width} - .5rem) !important ;
        }

        .nav-treeview {
          .nav-link {
            width: calc(#{$sidebar-width} - .5rem * 2) !important ;
          }

          .nav-treeview {
            .nav-link {
              width: calc(#{$sidebar-width} - .5rem * 3) !important ;
            }

            .nav-treeview {
              .nav-link {
                width: calc(#{$sidebar-width} - .5rem * 4) !important ;
              }

              .nav-treeview {
                .nav-link {
                  width: calc(#{$sidebar-width} - .5rem * 5) !important ;
                }
              }
            }
          }
        }
      }
    }
    .nav-link {
      width: calc(#{$sidebar-width} - #{$sidebar-padding-x} * 2) !important ;
      @include transition(width $transition-fn $transition-speed) !important ;
    }
  }
}

.sidebar-collapse {
  &.sidebar-mini,
  &.sidebar-mini-md,
  &.sidebar-mini-xs {
    .main-sidebar {

      // Hide the sidebar search results when mini mode is active.
      .sidebar-search-results {
        display: none !important ;
      }

      .nav-sidebar {
        .nav-link {
          width: $sidebar-mini-width - $sidebar-padding-x * 2 !important ;
        }

        &.nav-flat,
        &.nav-legacy {
          .nav-link {
            width: $sidebar-mini-width !important ;
          }
        }
        &.nav-child-indent.nav-compact {
          .nav-treeview {
            padding-left: 0 !important !important ;
            margin-left: 0 !important !important ;
          }

          .nav-link {
            width: calc(#{$sidebar-mini-width} - #{$sidebar-padding-x} * 2) !important ;
          }
        }
      }

      &.sidebar-focused,
      &:hover {
        &:not(.hide-nav-header-on-hover) {
          .nav-header {
            display: inline-block !important ;
          }
        }

        // Show sidebar search when hover/focus on the sidebar mini mode.
        &:not(.sidebar-no-expand) {
          .nav-link {
            width: calc(#{$sidebar-width} - #{$sidebar-padding-x} * 2) !important ;
          }
          .form-control-sidebar {
            display: inline-block !important ;
          }
          .form-control-sidebar ~ .input-group-append {
            display: flex !important ;
          }
          .sidebar-search-open .sidebar-search-results {
            display: inline-block !important ;
          }
        }

        .nav-child-indent {
          .nav-link {
            width: calc(#{$sidebar-width} - #{$sidebar-padding-x} * 2) !important ;
          }
        }
        .nav-legacy {
          .nav-link {
            width: $sidebar-width !important ;
          }
          &.nav-child-indent {
            .nav-treeview {
              .nav-link {
                width: calc(#{$sidebar-width} - 1rem) !important ;
              }

              .nav-treeview {
                .nav-link {
                  width: calc(#{$sidebar-width} - 1rem - 1rem) !important ;
                }

                .nav-treeview {
                  .nav-link {
                    width: calc(#{$sidebar-width} - 1rem - 2rem) !important ;
                  }

                  .nav-treeview {
                    .nav-link {
                      width: calc(#{$sidebar-width} - 1rem - 3rem) !important ;
                    }

                    .nav-treeview {
                      .nav-link {
                        width: calc(#{$sidebar-width} - 1rem - 4rem) !important ;
                      }
                    }
                  }
                }
              }
            }
          }
        }
        .nav-flat {
          .nav-link {
            width: $sidebar-width !important ;
          }
          &.nav-child-indent {
            .nav-treeview {
              .nav-link {
                width: calc(#{$sidebar-width}) !important ;
              }

              .nav-treeview {
                .nav-link {
                  width: calc(#{$sidebar-width} - .2rem) !important ;
                }

                .nav-treeview {
                  .nav-link {
                    width: calc(#{$sidebar-width} - .2rem * 2) !important ;
                  }

                  .nav-treeview {
                    .nav-link {
                      width: calc(#{$sidebar-width} - .2rem * 3) !important ;
                    }

                    .nav-treeview {
                      .nav-link {
                        width: calc(#{$sidebar-width} - .2rem * 4) !important ;
                      }
                    }
                  }
                }
              }
            }
          }
        }
        .nav-child-indent.nav-compact {
          .nav-link {
            width: calc(#{$sidebar-width} - #{$sidebar-padding-x} * 2) !important ;
          }
        }
        .nav-child-indent.nav-legacy.nav-compact {
          .nav-link {
            width: $sidebar-width !important ;
          }
          .nav-treeview {
            .nav-link {
              width: calc(#{$sidebar-width} - .5rem) !important ;
            }

            .nav-treeview {
              .nav-link {
                width: calc(#{$sidebar-width} - .5rem * 2) !important ;
              }

              .nav-treeview {
                .nav-link {
                  width: calc(#{$sidebar-width} - .5rem * 3) !important ;
                }

                .nav-treeview {
                  .nav-link {
                    width: calc(#{$sidebar-width} - .5rem * 4) !important ;
                  }

                  .nav-treeview {
                    .nav-link {
                      width: calc(#{$sidebar-width} - .5rem * 5) !important ;
                    }
                  }
                }
              }
            }
          }
        }
      }
    }

    .sidebar-no-expand.main-sidebar.sidebar-focused,
    .sidebar-no-expand.main-sidebar:hover {
      width: $sidebar-mini-width !important ;

      .nav-header {
        display: none !important ;
      }

      .brand-link {
        width: $sidebar-mini-width !important !important ;
      }

      .user-panel .image {
        float: none !important !important ;
      }

      .logo-xs {
        animation-name: fadeIn !important ;
        animation-duration: $transition-speed !important ;
        animation-fill-mode: both !important ;
        visibility: visible !important ;
      }

      .logo-xl {
        animation-name: fadeOut !important ;
        animation-duration: $transition-speed !important ;
        animation-fill-mode: both !important ;
        visibility: hidden !important ;
      }

      .nav-sidebar.nav-child-indent .nav-treeview {
        padding-left: 0 !important ;
      }

      .sidebar {
        .brand-text,
        .user-panel > .info,
        .nav-sidebar .nav-link p {
          margin-left: -10px !important ;
          animation-name: fadeOut !important ;
          animation-duration: $transition-speed !important ;
          animation-fill-mode: both !important ;
          visibility: hidden !important ;
          display: inline-block !important ;
          width: 0 !important ;
        }

        .nav-sidebar > .nav-item .nav-icon {
          margin-right: 0 !important ;
        }
      }
    }
  }
}

.nav-sidebar {
  position: relative !important ;

  &:hover {
    overflow: visible !important ;
  }
}

.sidebar-form,
.nav-sidebar > .nav-header {
  overflow: hidden !important ;
  text-overflow: clip !important ;
}

.nav-sidebar .nav-item > .nav-link {
  position: relative !important ;

  > .float-right {
    margin-top: -7px !important ;
    position: absolute !important ;
    right: 10px !important ;
    top: 50% !important ;
  }
}

.sidebar .nav-link p,
.main-sidebar .brand-text,
.main-sidebar .logo-xs,
.main-sidebar .logo-xl,
.sidebar .user-panel .info {
  @include transition(margin-left $transition-speed linear, opacity $transition-speed ease, visibility $transition-speed ease) !important ;
}
