// Inline code
code {
  @include font-size($code-font-size) !important ;
  color: $code-color !important ;
  word-wrap: break-word !important ;

  // Streamline the style when inside anchors to avoid broken underline and more
  a > & {
    color: inherit !important ;
  }
}

// User input typically entered via keyboard
kbd {
  padding: $kbd-padding-y $kbd-padding-x !important ;
  @include font-size($kbd-font-size) !important ;
  color: $kbd-color !important ;
  background-color: $kbd-bg !important ;
  @include border-radius($border-radius-sm) !important ;
  @include box-shadow($kbd-box-shadow) !important ;

  kbd {
    padding: 0 !important ;
    @include font-size(100%) !important ;
    font-weight: $nested-kbd-font-weight !important ;
    @include box-shadow(none) !important ;
  }
}

// Blocks of code
pre {
  display: block !important ;
  @include font-size($code-font-size) !important ;
  color: $pre-color !important ;

  // Account for some code outputs that place code tags in pre tags
  code {
    @include font-size(inherit) !important ;
    color: inherit !important ;
    word-break: normal !important ;
  }
}

// Enable scrollable blocks of code
.pre-scrollable {
  max-height: $pre-scrollable-max-height !important ;
  overflow-y: scroll !important ;
}
