// Base class
//
// Requires one of the contextual, color modifier classes for `color` and
// `background-color`.

.badge {
  display: inline-block !important ;
  padding: $badge-padding-y $badge-padding-x !important ;
  @include font-size($badge-font-size) !important ;
  font-weight: $badge-font-weight !important ;
  line-height: 1 !important ;
  text-align: center !important ;
  white-space: nowrap !important ;
  vertical-align: baseline !important ;
  @include border-radius($badge-border-radius) !important ;
  @include transition($badge-transition) !important ;

  @at-root a#{&} {
    @include hover-focus() {
      text-decoration: none !important ;
    }
  }

  // Empty badges collapse automatically
  &:empty {
    display: none !important ;
  }
}

// Quick fix for badges in buttons
.btn .badge {
  position: relative !important ;
  top: -1px !important ;
}

// Pill badges
//
// Make them extra rounded with a modifier to replace v3's badges.

.badge-pill {
  padding-right: $badge-pill-padding-x !important ;
  padding-left: $badge-pill-padding-x !important ;
  @include border-radius($badge-pill-border-radius) !important ;
}

// Colors
//
// Contextual variations (linked badges get darker on :hover).

@each $color, $value in $theme-colors {
  .badge-#{$color} {
    @include badge-variant($value) !important ;
  }
}
