// stylelint-disable selector-list-comma-newline-after

//
// Headings
//

h1, h2, h3, h4, h5, h6,
.h1, .h2, .h3, .h4, .h5, .h6 {
  margin-bottom: $headings-margin-bottom !important ;
  font-family: $headings-font-family !important ;
  font-weight: $headings-font-weight !important ;
  line-height: $headings-line-height !important ;
  color: $headings-color !important ;
}

h1, .h1 { @include font-size($h1-font-size) !important ; }
h2, .h2 { @include font-size($h2-font-size) !important ; }
h3, .h3 { @include font-size($h3-font-size) !important ; }
h4, .h4 { @include font-size($h4-font-size) !important ; }
h5, .h5 { @include font-size($h5-font-size) !important ; }
h6, .h6 { @include font-size($h6-font-size) !important ; }

.lead {
  @include font-size($lead-font-size) !important ;
  font-weight: $lead-font-weight !important ;
}

// Type display classes
.display-1 {
  @include font-size($display1-size) !important ;
  font-weight: $display1-weight !important ;
  line-height: $display-line-height !important ;
}
.display-2 {
  @include font-size($display2-size) !important ;
  font-weight: $display2-weight !important ;
  line-height: $display-line-height !important ;
}
.display-3 {
  @include font-size($display3-size) !important ;
  font-weight: $display3-weight !important ;
  line-height: $display-line-height !important ;
}
.display-4 {
  @include font-size($display4-size) !important ;
  font-weight: $display4-weight !important ;
  line-height: $display-line-height !important ;
}


//
// Horizontal rules
//

hr {
  margin-top: $hr-margin-y !important ;
  margin-bottom: $hr-margin-y !important ;
  border: 0 !important ;
  border-top: $hr-border-width solid $hr-border-color !important ;
}


//
// Emphasis
//

small,
.small {
  @include font-size($small-font-size) !important ;
  font-weight: $font-weight-normal !important ;
}

mark,
.mark {
  padding: $mark-padding !important ;
  background-color: $mark-bg !important ;
}


//
// Lists
//

.list-unstyled {
  @include list-unstyled() !important ;
}

// Inline turns list items into inline-block
.list-inline {
  @include list-unstyled() !important ;
}
.list-inline-item {
  display: inline-block !important ;

  &:not(:last-child) {
    margin-right: $list-inline-padding !important ;
  }
}


//
// Misc
//

// Builds on `abbr`
.initialism {
  @include font-size(90%) !important ;
  text-transform: uppercase !important ;
}

// Blockquotes
.blockquote {
  margin-bottom: $spacer !important ;
  @include font-size($blockquote-font-size) !important ;
}

.blockquote-footer {
  display: block !important ;
  @include font-size($blockquote-small-font-size) !important ;
  color: $blockquote-small-color !important ;

  &::before {
    content: "\2014\00A0" !important ; // em dash, nbsp
  }
}
