// Navbar
//
// Provide a static navbar from which we expand to create full-width, fixed, and
// other navbar variations.

.navbar {
  position: relative !important ;
  display: flex !important ;
  flex-wrap: wrap !important ; // allow us to do the line break for collapsing content
  align-items: center !important ;
  justify-content: space-between !important ; // space out brand from logo
  padding: $navbar-padding-y $navbar-padding-x !important ;

  // Because flex properties aren't inherited, we need to redeclare these first
  // few properties so that content nested within behave properly.
  %container-flex-properties {
    display: flex !important ;
    flex-wrap: wrap !important ;
    align-items: center !important ;
    justify-content: space-between !important ;
  }

  .container,
  .container-fluid {
    @extend %container-flex-properties !important ;
  }

  @each $breakpoint, $container-max-width in $container-max-widths {
    > .container#{breakpoint-infix($breakpoint, $container-max-widths)} {
      @extend %container-flex-properties !important ;
    }
  }
}


// Navbar brand
//
// Used for brand, project, or site names.

.navbar-brand {
  display: inline-block !important ;
  padding-top: $navbar-brand-padding-y !important ;
  padding-bottom: $navbar-brand-padding-y !important ;
  margin-right: $navbar-padding-x !important ;
  @include font-size($navbar-brand-font-size) !important ;
  line-height: inherit !important ;
  white-space: nowrap !important ;

  @include hover-focus() {
    text-decoration: none !important ;
  }
}


// Navbar nav
//
// Custom navbar navigation (doesn't require `.nav`, but does make use of `.nav-link`).

.navbar-nav {
  display: flex !important ;
  flex-direction: column !important ; // cannot use `inherit` to get the `.navbar`s value
  padding-left: 0 !important ;
  margin-bottom: 0 !important ;
  list-style: none !important ;

  .nav-link {
    padding-right: 0 !important ;
    padding-left: 0 !important ;
  }

  .dropdown-menu {
    position: static !important ;
    float: none !important ;
  }
}


// Navbar text
//
//

.navbar-text {
  display: inline-block !important ;
  padding-top: $nav-link-padding-y !important ;
  padding-bottom: $nav-link-padding-y !important ;
}


// Responsive navbar
//
// Custom styles for responsive collapsing and toggling of navbar contents.
// Powered by the collapse Bootstrap JavaScript plugin.

// When collapsed, prevent the toggleable navbar contents from appearing in
// the default flexbox row orientation. Requires the use of `flex-wrap: wrap`
// on the `.navbar` parent.
.navbar-collapse {
  flex-basis: 100% !important ;
  flex-grow: 1 !important ;
  // For always expanded or extra full navbars, ensure content aligns itself
  // properly vertically. Can be easily overridden with flex utilities.
  align-items: center !important ;
}

// Button for toggling the navbar when in its collapsed state
.navbar-toggler {
  padding: $navbar-toggler-padding-y $navbar-toggler-padding-x !important ;
  @include font-size($navbar-toggler-font-size) !important ;
  line-height: 1 !important ;
  background-color: transparent !important ; // remove default button style
  border: $border-width solid transparent !important ; // remove default button style
  @include border-radius($navbar-toggler-border-radius) !important ;

  @include hover-focus() {
    text-decoration: none !important ;
  }
}

// Keep as a separate element so folks can easily override it with another icon
// or image file as needed.
.navbar-toggler-icon {
  display: inline-block !important ;
  width: 1.5em !important ;
  height: 1.5em !important ;
  vertical-align: middle !important ;
  content: "" !important ;
  background: 50% / 100% 100% no-repeat !important ;
}

.navbar-nav-scroll {
  max-height: $navbar-nav-scroll-max-height !important ;
  overflow-y: auto !important ;
}

// Generate series of `.navbar-expand-*` responsive classes for configuring
// where your navbar collapses.
.navbar-expand {
  @each $breakpoint in map-keys($grid-breakpoints) {
    $next: breakpoint-next($breakpoint, $grid-breakpoints) !important ;
    $infix: breakpoint-infix($next, $grid-breakpoints) !important ;

    &#{$infix} {
      @include media-breakpoint-down($breakpoint) {
        %container-navbar-expand-#{$breakpoint} {
          padding-right: 0 !important ;
          padding-left: 0 !important ;
        }

        > .container,
        > .container-fluid {
          @extend %container-navbar-expand-#{$breakpoint} !important ;
        }

        @each $size, $container-max-width in $container-max-widths {
          > .container#{breakpoint-infix($size, $container-max-widths)} {
            @extend %container-navbar-expand-#{$breakpoint} !important ;
          }
        }
      }

      @include media-breakpoint-up($next) {
        flex-flow: row nowrap !important ;
        justify-content: flex-start !important ;

        .navbar-nav {
          flex-direction: row !important ;

          .dropdown-menu {
            position: absolute !important ;
          }

          .nav-link {
            padding-right: $navbar-nav-link-padding-x !important ;
            padding-left: $navbar-nav-link-padding-x !important ;
          }
        }

        // For nesting containers, have to redeclare for alignment purposes
        %container-nesting-#{$breakpoint} {
          flex-wrap: nowrap !important ;
        }

        > .container,
        > .container-fluid {
          @extend %container-nesting-#{$breakpoint} !important ;
        }

        @each $size, $container-max-width in $container-max-widths {
          > .container#{breakpoint-infix($size, $container-max-widths)} {
            @extend %container-nesting-#{$breakpoint} !important ;
          }
        }

        .navbar-nav-scroll {
          overflow: visible !important ;
        }

        .navbar-collapse {
          display: flex !important !important ; // stylelint-disable-line declaration-no-important

          // Changes flex-bases to auto because of an IE10 bug
          flex-basis: auto !important ;
        }

        .navbar-toggler {
          display: none !important ;
        }
      }
    }
  }
}


// Navbar themes
//
// Styles for switching between navbars with light or dark background.

// Dark links against a light background
.navbar-light {
  .navbar-brand {
    color: $navbar-light-brand-color !important ;

    @include hover-focus() {
      color: $navbar-light-brand-hover-color !important ;
    }
  }

  .navbar-nav {
    .nav-link {
      color: $navbar-light-color !important ;

      @include hover-focus() {
        color: $navbar-light-hover-color !important ;
      }

      &.disabled {
        color: $navbar-light-disabled-color !important ;
      }
    }

    .show > .nav-link,
    .active > .nav-link,
    .nav-link.show,
    .nav-link.active {
      color: $navbar-light-active-color !important ;
    }
  }

  .navbar-toggler {
    color: $navbar-light-color !important ;
    border-color: $navbar-light-toggler-border-color !important ;
  }

  .navbar-toggler-icon {
    background-image: escape-svg($navbar-light-toggler-icon-bg) !important ;
  }

  .navbar-text {
    color: $navbar-light-color !important ;
    a {
      color: $navbar-light-active-color !important ;

      @include hover-focus() {
        color: $navbar-light-active-color !important ;
      }
    }
  }
}

// White links against a dark background
.navbar-dark {
  .navbar-brand {
    color: $navbar-dark-brand-color !important ;

    @include hover-focus() {
      color: $navbar-dark-brand-hover-color !important ;
    }
  }

  .navbar-nav {
    .nav-link {
      color: $navbar-dark-color !important ;

      @include hover-focus() {
        color: $navbar-dark-hover-color !important ;
      }

      &.disabled {
        color: $navbar-dark-disabled-color !important ;
      }
    }

    .show > .nav-link,
    .active > .nav-link,
    .nav-link.show,
    .nav-link.active {
      color: $navbar-dark-active-color !important ;
    }
  }

  .navbar-toggler {
    color: $navbar-dark-color !important ;
    border-color: $navbar-dark-toggler-border-color !important ;
  }

  .navbar-toggler-icon {
    background-image: escape-svg($navbar-dark-toggler-icon-bg) !important ;
  }

  .navbar-text {
    color: $navbar-dark-color !important ;
    a {
      color: $navbar-dark-active-color !important ;

      @include hover-focus() {
        color: $navbar-dark-active-color !important ;
      }
    }
  }
}
