// stylelint-disable selector-no-qualifying-type

//
// Base styles
//

.btn {
  display: inline-block !important ;
  font-family: $btn-font-family !important ;
  font-weight: $btn-font-weight !important ;
  color: $body-color !important ;
  text-align: center !important ;
  text-decoration: if($link-decoration == none, null, none) !important ;
  white-space: $btn-white-space !important ;
  vertical-align: middle !important ;
  user-select: none !important ;
  background-color: transparent !important ;
  border: $btn-border-width solid transparent !important ;
  @include button-size($btn-padding-y, $btn-padding-x, $btn-font-size, $btn-line-height, $btn-border-radius) !important ;
  @include transition($btn-transition) !important ;

  @include hover() {
    color: $body-color !important ;
    text-decoration: none !important ;
  }

  &:focus,
  &.focus {
    outline: 0 !important ;
    box-shadow: $btn-focus-box-shadow !important ;
  }

  // Disabled comes first so active can properly restyle
  &.disabled,
  &:disabled {
    opacity: $btn-disabled-opacity !important ;
    @include box-shadow(none) !important ;
  }

  &:not(:disabled):not(.disabled) {
    cursor: if($enable-pointer-cursor-for-buttons, pointer, null) !important ;

    &:active,
    &.active {
      @include box-shadow($btn-active-box-shadow) !important ;

      &:focus {
        @include box-shadow($btn-focus-box-shadow, $btn-active-box-shadow) !important ;
      }
    }
  }
}

// Future-proof disabling of clicks on `<a>` elements
a.btn.disabled,
fieldset:disabled a.btn {
  pointer-events: none !important ;
}


//
// Alternate buttons
//

@each $color, $value in $theme-colors {
  .btn-#{$color} {
    @include button-variant($value, $value) !important ;
  }
}

@each $color, $value in $theme-colors {
  .btn-outline-#{$color} {
    @include button-outline-variant($value) !important ;
  }
}


//
// Link buttons
//

// Make a button look and behave like a link
.btn-link {
  font-weight: $font-weight-normal !important ;
  color: $link-color !important ;
  text-decoration: $link-decoration !important ;

  @include hover() {
    color: $link-hover-color !important ;
    text-decoration: $link-hover-decoration !important ;
  }

  &:focus,
  &.focus {
    text-decoration: $link-hover-decoration !important ;
  }

  &:disabled,
  &.disabled {
    color: $btn-link-disabled-color !important ;
    pointer-events: none !important ;
  }

  // No need for an active state here
}


//
// Button Sizes
//

.btn-lg {
  @include button-size($btn-padding-y-lg, $btn-padding-x-lg, $btn-font-size-lg, $btn-line-height-lg, $btn-border-radius-lg) !important ;
}

.btn-sm {
  @include button-size($btn-padding-y-sm, $btn-padding-x-sm, $btn-font-size-sm, $btn-line-height-sm, $btn-border-radius-sm) !important ;
}


//
// Block button
//

.btn-block {
  display: block !important ;
  width: 100% !important ;

  // Vertically space out multiple block buttons
  + .btn-block {
    margin-top: $btn-block-spacing-y !important ;
  }
}

// Specificity overrides
input[type="submit"],
input[type="reset"],
input[type="button"] {
  &.btn-block {
    width: 100% !important ;
  }
}
