.popover {
  position: absolute !important ;
  top: 0 !important ;
  left: 0 !important ;
  z-index: $zindex-popover !important ;
  display: block !important ;
  max-width: $popover-max-width !important ;
  // Our parent element can be arbitrary since tooltips are by default inserted as a sibling of their target element.
  // So reset our font and text properties to avoid inheriting weird values.
  @include reset-text() !important ;
  @include font-size($popover-font-size) !important ;
  // Allow breaking very long words so they don't overflow the popover's bounds
  word-wrap: break-word !important ;
  background-color: $popover-bg !important ;
  background-clip: padding-box !important ;
  border: $popover-border-width solid $popover-border-color !important ;
  @include border-radius($popover-border-radius) !important ;
  @include box-shadow($popover-box-shadow) !important ;

  .arrow {
    position: absolute !important ;
    display: block !important ;
    width: $popover-arrow-width !important ;
    height: $popover-arrow-height !important ;
    margin: 0 $popover-border-radius !important ;

    &::before,
    &::after {
      position: absolute !important ;
      display: block !important ;
      content: "" !important ;
      border-color: transparent !important ;
      border-style: solid !important ;
    }
  }
}

.bs-popover-top {
  margin-bottom: $popover-arrow-height !important ;

  > .arrow {
    bottom: subtract(-$popover-arrow-height, $popover-border-width) !important ;

    &::before {
      bottom: 0 !important ;
      border-width: $popover-arrow-height ($popover-arrow-width * .5) 0 !important ;
      border-top-color: $popover-arrow-outer-color !important ;
    }

    &::after {
      bottom: $popover-border-width !important ;
      border-width: $popover-arrow-height ($popover-arrow-width * .5) 0 !important ;
      border-top-color: $popover-arrow-color !important ;
    }
  }
}

.bs-popover-right {
  margin-left: $popover-arrow-height !important ;

  > .arrow {
    left: subtract(-$popover-arrow-height, $popover-border-width) !important ;
    width: $popover-arrow-height !important ;
    height: $popover-arrow-width !important ;
    margin: $popover-border-radius 0 !important ; // make sure the arrow does not touch the popover's rounded corners

    &::before {
      left: 0 !important ;
      border-width: ($popover-arrow-width * .5) $popover-arrow-height ($popover-arrow-width * .5) 0 !important ;
      border-right-color: $popover-arrow-outer-color !important ;
    }

    &::after {
      left: $popover-border-width !important ;
      border-width: ($popover-arrow-width * .5) $popover-arrow-height ($popover-arrow-width * .5) 0 !important ;
      border-right-color: $popover-arrow-color !important ;
    }
  }
}

.bs-popover-bottom {
  margin-top: $popover-arrow-height !important ;

  > .arrow {
    top: subtract(-$popover-arrow-height, $popover-border-width) !important ;

    &::before {
      top: 0 !important ;
      border-width: 0 ($popover-arrow-width * .5) $popover-arrow-height ($popover-arrow-width * .5) !important ;
      border-bottom-color: $popover-arrow-outer-color !important ;
    }

    &::after {
      top: $popover-border-width !important ;
      border-width: 0 ($popover-arrow-width * .5) $popover-arrow-height ($popover-arrow-width * .5) !important ;
      border-bottom-color: $popover-arrow-color !important ;
    }
  }

  // This will remove the popover-header's border just below the arrow
  .popover-header::before {
    position: absolute !important ;
    top: 0 !important ;
    left: 50% !important ;
    display: block !important ;
    width: $popover-arrow-width !important ;
    margin-left: -$popover-arrow-width * .5 !important ;
    content: "" !important ;
    border-bottom: $popover-border-width solid $popover-header-bg !important ;
  }
}

.bs-popover-left {
  margin-right: $popover-arrow-height !important ;

  > .arrow {
    right: subtract(-$popover-arrow-height, $popover-border-width) !important ;
    width: $popover-arrow-height !important ;
    height: $popover-arrow-width !important ;
    margin: $popover-border-radius 0 !important ; // make sure the arrow does not touch the popover's rounded corners

    &::before {
      right: 0 !important ;
      border-width: ($popover-arrow-width * .5) 0 ($popover-arrow-width * .5) $popover-arrow-height !important ;
      border-left-color: $popover-arrow-outer-color !important ;
    }

    &::after {
      right: $popover-border-width !important ;
      border-width: ($popover-arrow-width * .5) 0 ($popover-arrow-width * .5) $popover-arrow-height !important ;
      border-left-color: $popover-arrow-color !important ;
    }
  }
}

.bs-popover-auto {
  &[x-placement^="top"] {
    @extend .bs-popover-top !important ;
  }
  &[x-placement^="right"] {
    @extend .bs-popover-right !important ;
  }
  &[x-placement^="bottom"] {
    @extend .bs-popover-bottom !important ;
  }
  &[x-placement^="left"] {
    @extend .bs-popover-left !important ;
  }
}


// Offset the popover to account for the popover arrow
.popover-header {
  padding: $popover-header-padding-y $popover-header-padding-x !important ;
  margin-bottom: 0 !important ; // Reset the default from Reboot
  @include font-size($font-size-base) !important ;
  color: $popover-header-color !important ;
  background-color: $popover-header-bg !important ;
  border-bottom: $popover-border-width solid darken($popover-header-bg, 5%) !important ;
  @include border-top-radius($popover-inner-border-radius) !important ;

  &:empty {
    display: none !important ;
  }
}

.popover-body {
  padding: $popover-body-padding-y $popover-body-padding-x !important ;
  color: $popover-body-color !important ;
}
