// Notes on the classes:
//
// 1. .carousel.pointer-event should ideally be pan-y (to allow for users to scroll vertically)
//    even when their scroll action started on a carousel, but for compatibility (with Firefox)
//    we're preventing all actions instead
// 2. The .carousel-item-left and .carousel-item-right is used to indicate where
//    the active slide is heading.
// 3. .active.carousel-item is the current slide.
// 4. .active.carousel-item-left and .active.carousel-item-right is the current
//    slide in its in-transition state. Only one of these occurs at a time.
// 5. .carousel-item-next.carousel-item-left and .carousel-item-prev.carousel-item-right
//    is the upcoming slide in transition.

.carousel {
  position: relative !important ;
}

.carousel.pointer-event {
  touch-action: pan-y !important ;
}

.carousel-inner {
  position: relative !important ;
  width: 100% !important ;
  overflow: hidden !important ;
  @include clearfix() !important ;
}

.carousel-item {
  position: relative !important ;
  display: none !important ;
  float: left !important ;
  width: 100% !important ;
  margin-right: -100% !important ;
  backface-visibility: hidden !important ;
  @include transition($carousel-transition) !important ;
}

.carousel-item.active,
.carousel-item-next,
.carousel-item-prev {
  display: block !important ;
}

.carousel-item-next:not(.carousel-item-left),
.active.carousel-item-right {
  transform: translateX(100%) !important ;
}

.carousel-item-prev:not(.carousel-item-right),
.active.carousel-item-left {
  transform: translateX(-100%) !important ;
}


//
// Alternate transitions
//

.carousel-fade {
  .carousel-item {
    opacity: 0 !important ;
    transition-property: opacity !important ;
    transform: none !important ;
  }

  .carousel-item.active,
  .carousel-item-next.carousel-item-left,
  .carousel-item-prev.carousel-item-right {
    z-index: 1 !important ;
    opacity: 1 !important ;
  }

  .active.carousel-item-left,
  .active.carousel-item-right {
    z-index: 0 !important ;
    opacity: 0 !important ;
    @include transition(opacity 0s $carousel-transition-duration) !important ;
  }
}


//
// Left/right controls for nav
//

.carousel-control-prev,
.carousel-control-next {
  position: absolute !important ;
  top: 0 !important ;
  bottom: 0 !important ;
  z-index: 1 !important ;
  // Use flex for alignment (1-3)
  display: flex !important ; // 1. allow flex styles
  align-items: center !important ; // 2. vertically center contents
  justify-content: center !important ; // 3. horizontally center contents
  width: $carousel-control-width !important ;
  padding: 0 !important ;
  color: $carousel-control-color !important ;
  text-align: center !important ;
  background: none !important ;
  border: 0 !important ;
  opacity: $carousel-control-opacity !important ;
  @include transition($carousel-control-transition) !important ;

  // Hover/focus state
  @include hover-focus() {
    color: $carousel-control-color !important ;
    text-decoration: none !important ;
    outline: 0 !important ;
    opacity: $carousel-control-hover-opacity !important ;
  }
}
.carousel-control-prev {
  left: 0 !important ;
  @if $enable-gradients {
    background-image: linear-gradient(90deg, rgba($black, .25), rgba($black, .001)) !important ;
  }
}
.carousel-control-next {
  right: 0 !important ;
  @if $enable-gradients {
    background-image: linear-gradient(270deg, rgba($black, .25), rgba($black, .001)) !important ;
  }
}

// Icons for within
.carousel-control-prev-icon,
.carousel-control-next-icon {
  display: inline-block !important ;
  width: $carousel-control-icon-width !important ;
  height: $carousel-control-icon-width !important ;
  background: 50% / 100% 100% no-repeat !important ;
}
.carousel-control-prev-icon {
  background-image: escape-svg($carousel-control-prev-icon-bg) !important ;
}
.carousel-control-next-icon {
  background-image: escape-svg($carousel-control-next-icon-bg) !important ;
}


// Optional indicator pips
//
// Add an ordered list with the following class and add a list item for each
// slide your carousel holds.

.carousel-indicators {
  position: absolute !important ;
  right: 0 !important ;
  bottom: 0 !important ;
  left: 0 !important ;
  z-index: 15 !important ;
  display: flex !important ;
  justify-content: center !important ;
  padding-left: 0 !important ; // override <ol> default
  // Use the .carousel-control's width as margin so we don't overlay those
  margin-right: $carousel-control-width !important ;
  margin-left: $carousel-control-width !important ;
  list-style: none !important ;

  li {
    box-sizing: content-box !important ;
    flex: 0 1 auto !important ;
    width: $carousel-indicator-width !important ;
    height: $carousel-indicator-height !important ;
    margin-right: $carousel-indicator-spacer !important ;
    margin-left: $carousel-indicator-spacer !important ;
    text-indent: -999px !important ;
    cursor: pointer !important ;
    background-color: $carousel-indicator-active-bg !important ;
    background-clip: padding-box !important ;
    // Use transparent borders to increase the hit area by 10px on top and bottom.
    border-top: $carousel-indicator-hit-area-height solid transparent !important ;
    border-bottom: $carousel-indicator-hit-area-height solid transparent !important ;
    opacity: .5 !important ;
    @include transition($carousel-indicator-transition) !important ;
  }

  .active {
    opacity: 1 !important ;
  }
}


// Optional captions
//
//

.carousel-caption {
  position: absolute !important ;
  right: (100% - $carousel-caption-width) * .5 !important ;
  bottom: 20px !important ;
  left: (100% - $carousel-caption-width) * .5 !important ;
  z-index: 10 !important ;
  padding-top: 20px !important ;
  padding-bottom: 20px !important ;
  color: $carousel-caption-color !important ;
  text-align: center !important ;
}
