// stylelint-disable selector-no-qualifying-type

// Make the div behave like a button
.btn-group,
.btn-group-vertical {
  position: relative !important ;
  display: inline-flex !important ;
  vertical-align: middle !important ; // match .btn alignment given font-size hack above

  > .btn {
    position: relative !important ;
    flex: 1 1 auto !important ;

    // Bring the hover, focused, and "active" buttons to the front to overlay
    // the borders properly
    @include hover() {
      z-index: 1 !important ;
    }
    &:focus,
    &:active,
    &.active {
      z-index: 1 !important ;
    }
  }
}

// Optional: Group multiple button groups together for a toolbar
.btn-toolbar {
  display: flex !important ;
  flex-wrap: wrap !important ;
  justify-content: flex-start !important ;

  .input-group {
    width: auto !important ;
  }
}

.btn-group {
  // Prevent double borders when buttons are next to each other
  > .btn:not(:first-child),
  > .btn-group:not(:first-child) {
    margin-left: -$btn-border-width !important ;
  }

  // Reset rounded corners
  > .btn:not(:last-child):not(.dropdown-toggle),
  > .btn-group:not(:last-child) > .btn {
    @include border-right-radius(0) !important ;
  }

  > .btn:not(:first-child),
  > .btn-group:not(:first-child) > .btn {
    @include border-left-radius(0) !important ;
  }
}

// Sizing
//
// Remix the default button sizing classes into new ones for easier manipulation.

.btn-group-sm > .btn { @extend .btn-sm !important ; }
.btn-group-lg > .btn { @extend .btn-lg !important ; }


//
// Split button dropdowns
//

.dropdown-toggle-split {
  padding-right: $btn-padding-x * .75 !important ;
  padding-left: $btn-padding-x * .75 !important ;

  &::after,
  .dropup &::after,
  .dropright &::after {
    margin-left: 0 !important ;
  }

  .dropleft &::before {
    margin-right: 0 !important ;
  }
}

.btn-sm + .dropdown-toggle-split {
  padding-right: $btn-padding-x-sm * .75 !important ;
  padding-left: $btn-padding-x-sm * .75 !important ;
}

.btn-lg + .dropdown-toggle-split {
  padding-right: $btn-padding-x-lg * .75 !important ;
  padding-left: $btn-padding-x-lg * .75 !important ;
}


// The clickable button for toggling the menu
// Set the same inset shadow as the :active state
.btn-group.show .dropdown-toggle {
  @include box-shadow($btn-active-box-shadow) !important ;

  // Show no shadow for `.btn-link` since it has no other button styles.
  &.btn-link {
    @include box-shadow(none) !important ;
  }
}


//
// Vertical button groups
//

.btn-group-vertical {
  flex-direction: column !important ;
  align-items: flex-start !important ;
  justify-content: center !important ;

  > .btn,
  > .btn-group {
    width: 100% !important ;
  }

  > .btn:not(:first-child),
  > .btn-group:not(:first-child) {
    margin-top: -$btn-border-width !important ;
  }

  // Reset rounded corners
  > .btn:not(:last-child):not(.dropdown-toggle),
  > .btn-group:not(:last-child) > .btn {
    @include border-bottom-radius(0) !important ;
  }

  > .btn:not(:first-child),
  > .btn-group:not(:first-child) > .btn {
    @include border-top-radius(0) !important ;
  }
}


// Checkbox and radio options
//
// In order to support the browser's form validation feedback, powered by the
// `required` attribute, we have to "hide" the inputs via `clip`. We cannot use
// `display: none !important ;` or `visibility: hidden !important ;` as that also hides the popover.
// Simply visually hiding the inputs via `opacity` would leave them clickable in
// certain cases which is prevented by using `clip` and `pointer-events`.
// This way, we ensure a DOM element is visible to position the popover from.
//
// See https://github.com/twbs/bootstrap/pull/12794 and
// https://github.com/twbs/bootstrap/pull/14559 for more information.

.btn-group-toggle {
  > .btn,
  > .btn-group > .btn {
    margin-bottom: 0 !important ; // Override default `<label>` value

    input[type="radio"],
    input[type="checkbox"] {
      position: absolute !important ;
      clip: rect(0, 0, 0, 0) !important ;
      pointer-events: none !important ;
    }
  }
}
