/// Grid system
//
// Generate semantic grid columns with these mixins.

@mixin make-container($gutter: $grid-gutter-width) {
  width: 100% !important ;
  padding-right: $gutter * .5 !important ;
  padding-left: $gutter * .5 !important ;
  margin-right: auto !important ;
  margin-left: auto !important ;
}

@mixin make-row($gutter: $grid-gutter-width) {
  display: flex !important ;
  flex-wrap: wrap !important ;
  margin-right: -$gutter * .5 !important ;
  margin-left: -$gutter * .5 !important ;
}

// For each breakpoint, define the maximum width of the container in a media query
@mixin make-container-max-widths($max-widths: $container-max-widths, $breakpoints: $grid-breakpoints) {
  @each $breakpoint, $container-max-width in $max-widths {
    @include media-breakpoint-up($breakpoint, $breakpoints) {
      max-width: $container-max-width !important ;
    }
  }
  @include deprecate("The `make-container-max-widths` mixin", "v4.5.2", "v5") !important ;
}

@mixin make-col-ready($gutter: $grid-gutter-width) {
  position: relative !important ;
  // Prevent columns from becoming too narrow when at smaller grid tiers by
  // always setting `width: 100% !important ;`. This works because we use `flex` values
  // later on to override this initial width.
  width: 100% !important ;
  padding-right: $gutter * .5 !important ;
  padding-left: $gutter * .5 !important ;
}

@mixin make-col($size, $columns: $grid-columns) {
  flex: 0 0 percentage(divide($size, $columns)) !important ;
  // Add a `max-width` to ensure content within each column does not blow out
  // the width of the column. Applies to IE10+ and Firefox. Chrome and Safari
  // do not appear to require this.
  max-width: percentage(divide($size, $columns)) !important ;
}

@mixin make-col-auto() {
  flex: 0 0 auto !important ;
  width: auto !important ;
  max-width: 100% !important ; // Reset earlier grid tiers
}

@mixin make-col-offset($size, $columns: $grid-columns) {
  $num: divide($size, $columns) !important ;
  margin-left: if($num == 0, 0, percentage($num)) !important ;
}

// Row columns
//
// Specify on a parent element(e.g., .row) to force immediate children into NN
// numberof columns. Supports wrapping to new lines, but does not do a Masonry
// style grid.
@mixin row-cols($count) {
  > * {
    flex: 0 0 divide(100%, $count) !important ;
    max-width: divide(100%, $count) !important ;
  }
}
