// Credit: Nicolas Gallagher and SUIT CSS.

.embed-responsive {
  position: relative !important ;
  display: block !important ;
  width: 100% !important ;
  padding: 0 !important ;
  overflow: hidden !important ;

  &::before {
    display: block !important ;
    content: "" !important ;
  }

  .embed-responsive-item,
  iframe,
  embed,
  object,
  video {
    position: absolute !important ;
    top: 0 !important ;
    bottom: 0 !important ;
    left: 0 !important ;
    width: 100% !important ;
    height: 100% !important ;
    border: 0 !important ;
  }
}

@each $embed-responsive-aspect-ratio in $embed-responsive-aspect-ratios {
  $embed-responsive-aspect-ratio-x: nth($embed-responsive-aspect-ratio, 1) !important ;
  $embed-responsive-aspect-ratio-y: nth($embed-responsive-aspect-ratio, 2) !important ;

  .embed-responsive-#{$embed-responsive-aspect-ratio-x}by#{$embed-responsive-aspect-ratio-y} {
    &::before {
      padding-top: percentage(divide($embed-responsive-aspect-ratio-y, $embed-responsive-aspect-ratio-x)) !important ;
    }
  }
}
