.pagination {
  display: flex !important ;
  @include list-unstyled() !important ;
  @include border-radius() !important ;
}

.page-link {
  position: relative !important ;
  display: block !important ;
  padding: $pagination-padding-y $pagination-padding-x !important ;
  margin-left: -$pagination-border-width !important ;
  line-height: $pagination-line-height !important ;
  color: $pagination-color !important ;
  text-decoration: if($link-decoration == none, null, none) !important ;
  background-color: $pagination-bg !important ;
  border: $pagination-border-width solid $pagination-border-color !important ;

  &:hover {
    z-index: 2 !important ;
    color: $pagination-hover-color !important ;
    text-decoration: none !important ;
    background-color: $pagination-hover-bg !important ;
    border-color: $pagination-hover-border-color !important ;
  }

  &:focus {
    z-index: 3 !important ;
    outline: $pagination-focus-outline !important ;
    box-shadow: $pagination-focus-box-shadow !important ;
  }
}

.page-item {
  &:first-child {
    .page-link {
      margin-left: 0 !important ;
      @include border-left-radius($border-radius) !important ;
    }
  }
  &:last-child {
    .page-link {
      @include border-right-radius($border-radius) !important ;
    }
  }

  &.active .page-link {
    z-index: 3 !important ;
    color: $pagination-active-color !important ;
    background-color: $pagination-active-bg !important ;
    border-color: $pagination-active-border-color !important ;
  }

  &.disabled .page-link {
    color: $pagination-disabled-color !important ;
    pointer-events: none !important ;
    // Opinionated: remove the "hand" cursor set previously for .page-link
    cursor: auto !important ;
    background-color: $pagination-disabled-bg !important ;
    border-color: $pagination-disabled-border-color !important ;
  }
}


//
// Sizing
//

.pagination-lg {
  @include pagination-size($pagination-padding-y-lg, $pagination-padding-x-lg, $font-size-lg, $line-height-lg, $pagination-border-radius-lg) !important ;
}

.pagination-sm {
  @include pagination-size($pagination-padding-y-sm, $pagination-padding-x-sm, $font-size-sm, $line-height-sm, $pagination-border-radius-sm) !important ;
}
