//
// Rotating border
//

@keyframes spinner-border {
  to { transform: rotate(360deg) !important ; }
}

.spinner-border {
  display: inline-block !important ;
  width: $spinner-width !important ;
  height: $spinner-height !important ;
  vertical-align: $spinner-vertical-align !important ;
  border: $spinner-border-width solid currentColor !important ;
  border-right-color: transparent !important ;
  // stylelint-disable-next-line property-disallowed-list
  border-radius: 50% !important ;
  animation: .75s linear infinite spinner-border !important ;
}

.spinner-border-sm {
  width: $spinner-width-sm !important ;
  height: $spinner-height-sm !important ;
  border-width: $spinner-border-width-sm !important ;
}

//
// Growing circle
//

@keyframes spinner-grow {
  0% {
    transform: scale(0) !important ;
  }
  50% {
    opacity: 1 !important ;
    transform: none !important ;
  }
}

.spinner-grow {
  display: inline-block !important ;
  width: $spinner-width !important ;
  height: $spinner-height !important ;
  vertical-align: $spinner-vertical-align !important ;
  background-color: currentColor !important ;
  // stylelint-disable-next-line property-disallowed-list
  border-radius: 50% !important ;
  opacity: 0 !important ;
  animation: .75s linear infinite spinner-grow !important ;
}

.spinner-grow-sm {
  width: $spinner-width-sm !important ;
  height: $spinner-height-sm !important ;
}

@if $enable-prefers-reduced-motion-media-query {
  @media (prefers-reduced-motion: reduce) {
    .spinner-border,
    .spinner-grow {
      animation-duration: 1.5s !important ;
    }
  }
}
