//
// Base styles
//

.alert {
  position: relative !important ;
  padding: $alert-padding-y $alert-padding-x !important ;
  margin-bottom: $alert-margin-bottom !important ;
  border: $alert-border-width solid transparent !important ;
  @include border-radius($alert-border-radius) !important ;
}

// Headings for larger alerts
.alert-heading {
  // Specified to prevent conflicts of changing $headings-color
  color: inherit !important ;
}

// Provide class for links that match alerts
.alert-link {
  font-weight: $alert-link-font-weight !important ;
}


// Dismissible alerts
//
// Expand the right padding and account for the close button's positioning.

.alert-dismissible {
  padding-right: $close-font-size + $alert-padding-x * 2 !important ;

  // Adjust close link position
  .close {
    position: absolute !important ;
    top: 0 !important ;
    right: 0 !important ;
    z-index: 2 !important ;
    padding: $alert-padding-y $alert-padding-x !important ;
    color: inherit !important ;
  }
}


// Alternate styles
//
// Generate contextual modifier classes for colorizing the alert.

@each $color, $value in $theme-colors {
  .alert-#{$color} {
    @include alert-variant(theme-color-level($color, $alert-bg-level), theme-color-level($color, $alert-border-level), theme-color-level($color, $alert-color-level)) !important ;
  }
}
