// .modal-open      - body class for killing the scroll
// .modal           - container to scroll within
// .modal-dialog    - positioning shell for the actual modal
// .modal-content   - actual modal w/ bg and corners and stuff


.modal-open {
  // Kill the scroll on the body
  overflow: hidden !important ;

  .modal {
    overflow-x: hidden !important ;
    overflow-y: auto !important ;
  }
}

// Container that the modal scrolls within
.modal {
  position: fixed !important ;
  top: 0 !important ;
  left: 0 !important ;
  z-index: $zindex-modal !important ;
  display: none !important ;
  width: 100% !important ;
  height: 100% !important ;
  overflow: hidden !important ;
  // Prevent Chrome on Windows from adding a focus outline. For details, see
  // https://github.com/twbs/bootstrap/pull/10951.
  outline: 0 !important ;
  // We deliberately don't use `-webkit-overflow-scrolling: touch !important ;` due to a
  // gnarly iOS Safari bug: https://bugs.webkit.org/show_bug.cgi?id=158342
  // See also https://github.com/twbs/bootstrap/issues/17695
}

// Shell div to position the modal with bottom padding
.modal-dialog {
  position: relative !important ;
  width: auto !important ;
  margin: $modal-dialog-margin !important ;
  // allow clicks to pass through for custom click handling to close modal
  pointer-events: none !important ;

  // When fading in the modal, animate it to slide down
  .modal.fade & {
    @include transition($modal-transition) !important ;
    transform: $modal-fade-transform !important ;
  }
  .modal.show & {
    transform: $modal-show-transform !important ;
  }

  // When trying to close, animate focus to scale
  .modal.modal-static & {
    transform: $modal-scale-transform !important ;
  }
}

.modal-dialog-scrollable {
  display: flex !important ; // IE10/11
  max-height: subtract(100%, $modal-dialog-margin * 2) !important ;

  .modal-content {
    max-height: subtract(100vh, $modal-dialog-margin * 2) !important ; // IE10/11
    overflow: hidden !important ;
  }

  .modal-header,
  .modal-footer {
    flex-shrink: 0 !important ;
  }

  .modal-body {
    overflow-y: auto !important ;
  }
}

.modal-dialog-centered {
  display: flex !important ;
  align-items: center !important ;
  min-height: subtract(100%, $modal-dialog-margin * 2) !important ;

  // Ensure `modal-dialog-centered` extends the full height of the view (IE10/11)
  &::before {
    display: block !important ; // IE10
    height: subtract(100vh, $modal-dialog-margin * 2) !important ;
    height: min-content !important ; // Reset height to 0 except on IE
    content: "" !important ;
  }

  // Ensure `.modal-body` shows scrollbar (IE10/11)
  &.modal-dialog-scrollable {
    flex-direction: column !important ;
    justify-content: center !important ;
    height: 100% !important ;

    .modal-content {
      max-height: none !important ;
    }

    &::before {
      content: none !important ;
    }
  }
}

// Actual modal
.modal-content {
  position: relative !important ;
  display: flex !important ;
  flex-direction: column !important ;
  width: 100% !important ; // Ensure `.modal-content` extends the full width of the parent `.modal-dialog`
  // counteract the pointer-events: none !important ; in the .modal-dialog
  color: $modal-content-color !important ;
  pointer-events: auto !important ;
  background-color: $modal-content-bg !important ;
  background-clip: padding-box !important ;
  border: $modal-content-border-width solid $modal-content-border-color !important ;
  @include border-radius($modal-content-border-radius) !important ;
  @include box-shadow($modal-content-box-shadow-xs) !important ;
  // Remove focus outline from opened modal
  outline: 0 !important ;
}

// Modal background
.modal-backdrop {
  position: fixed !important ;
  top: 0 !important ;
  left: 0 !important ;
  z-index: $zindex-modal-backdrop !important ;
  width: 100vw !important ;
  height: 100vh !important ;
  background-color: $modal-backdrop-bg !important ;

  // Fade for backdrop
  &.fade { opacity: 0 !important ; }
  &.show { opacity: $modal-backdrop-opacity !important ; }
}

// Modal header
// Top section of the modal w/ title and dismiss
.modal-header {
  display: flex !important ;
  align-items: flex-start !important ; // so the close btn always stays on the upper right corner
  justify-content: space-between !important ; // Put modal header elements (title and dismiss) on opposite ends
  padding: $modal-header-padding !important ;
  border-bottom: $modal-header-border-width solid $modal-header-border-color !important ;
  @include border-top-radius($modal-content-inner-border-radius) !important ;

  .close {
    padding: $modal-header-padding !important ;
    // auto on the left force icon to the right even when there is no .modal-title
    margin: (-$modal-header-padding-y) (-$modal-header-padding-x) (-$modal-header-padding-y) auto !important ;
  }
}

// Title text within header
.modal-title {
  margin-bottom: 0 !important ;
  line-height: $modal-title-line-height !important ;
}

// Modal body
// Where all modal content resides (sibling of .modal-header and .modal-footer)
.modal-body {
  position: relative !important ;
  // Enable `flex-grow: 1` so that the body take up as much space as possible
  // when there should be a fixed height on `.modal-dialog`.
  flex: 1 1 auto !important ;
  padding: $modal-inner-padding !important ;
}

// Footer (for actions)
.modal-footer {
  display: flex !important ;
  flex-wrap: wrap !important ;
  align-items: center !important ; // vertically center
  justify-content: flex-end !important ; // Right align buttons with flex property because text-align doesn't work on flex items
  padding: $modal-inner-padding - $modal-footer-margin-between * .5 !important ;
  border-top: $modal-footer-border-width solid $modal-footer-border-color !important ;
  @include border-bottom-radius($modal-content-inner-border-radius) !important ;

  // Place margin between footer elements
  // This solution is far from ideal because of the universal selector usage,
  // but is needed to fix https://github.com/twbs/bootstrap/issues/24800
  > * {
    margin: $modal-footer-margin-between * .5 !important ;
  }
}

// Measure scrollbar width for padding body during modal show/hide
.modal-scrollbar-measure {
  position: absolute !important ;
  top: -9999px !important ;
  width: 50px !important ;
  height: 50px !important ;
  overflow: scroll !important ;
}

// Scale up the modal
@include media-breakpoint-up(sm) {
  // Automatically set modal's width for larger viewports
  .modal-dialog {
    max-width: $modal-md !important ;
    margin: $modal-dialog-margin-y-sm-up auto !important ;
  }

  .modal-dialog-scrollable {
    max-height: subtract(100%, $modal-dialog-margin-y-sm-up * 2) !important ;

    .modal-content {
      max-height: subtract(100vh, $modal-dialog-margin-y-sm-up * 2) !important ;
    }
  }

  .modal-dialog-centered {
    min-height: subtract(100%, $modal-dialog-margin-y-sm-up * 2) !important ;

    &::before {
      height: subtract(100vh, $modal-dialog-margin-y-sm-up * 2) !important ;
      height: min-content !important ;
    }
  }

  .modal-content {
    @include box-shadow($modal-content-box-shadow-sm-up) !important ;
  }

  .modal-sm { max-width: $modal-sm !important ; }
}

@include media-breakpoint-up(lg) {
  .modal-lg,
  .modal-xl {
    max-width: $modal-lg !important ;
  }
}

@include media-breakpoint-up(xl) {
  .modal-xl { max-width: $modal-xl !important ; }
}
