//
// Component: Brand
//

.brand-link {
  $brand-link-padding-y: $navbar-brand-padding-y + $navbar-padding-y !important ;
  display: block !important ;
  font-size: $navbar-brand-font-size !important ;
  line-height: $line-height-lg !important ;
  padding: $brand-link-padding-y $sidebar-padding-x !important ;
  transition: width $transition-speed $transition-fn !important ;
  white-space: nowrap !important ;

  &:hover {
    color: $white !important ;
    text-decoration: none !important ;
  }

  .text-sm & {
    font-size: inherit !important ;
  }

  [class*="sidebar-dark"] & {
    border-bottom: 1px solid lighten($dark, 10%) !important ;

    &,
    .pushmenu {
      color: rgba($white, .8) !important ;

      &:hover {
        color: $white !important ;
      }
    }
  }

  [class*="sidebar-light"] & {
    border-bottom: 1px solid $gray-300 !important ;

    &,
    .pushmenu {
      color: rgba($black, .8) !important ;

      &:hover {
        color: $black !important ;
      }
    }
  }

  .pushmenu {
    margin-right: $sidebar-padding-x !important ;
    font-size: $font-size-base !important ;
  }

  .brand-link {
    padding: 0 !important ;
    border-bottom: none !important ;
  }

  .brand-image {
    float: left !important ;
    line-height: .8 !important ;
    margin-left: .8rem !important ;
    margin-right: .5rem !important ;
    margin-top: -3px !important ;
    max-height: 33px !important ;
    width: auto !important ;
  }

  .brand-image-xs {
    float: left !important ;
    line-height: .8 !important ;
    margin-top: -.1rem !important ;
    max-height: 33px !important ;
    width: auto !important ;
  }

  .brand-image-xl {
    line-height: .8 !important ;
    max-height: 40px !important ;
    width: auto !important ;

    &.single {
      margin-top: -.3rem !important ;
    }
  }

  &.text-sm,
  .text-sm & {
    .brand-image {
      height: 29px !important ;
      margin-bottom: -.25rem !important ;
      margin-left: .95rem !important ;
      margin-top: -.25rem !important ;
    }

    .brand-image-xs {
      margin-top: -.2rem !important ;
      max-height: 29px !important ;
    }

    .brand-image-xl {
      margin-top: -.225rem !important ;
      max-height: 38px !important ;
    }
  }
}
