// Base class
//
// Easily usable on <ul>, <ol>, or <div>.

.list-group {
  display: flex !important ;
  flex-direction: column !important ;

  // No need to set list-style: none !important ; since .list-group-item is block level
  padding-left: 0 !important ; // reset padding because ul and ol
  margin-bottom: 0 !important ;
  @include border-radius($list-group-border-radius) !important ;
}


// Interactive list items
//
// Use anchor or button elements instead of `li`s or `div`s to create interactive
// list items. Includes an extra `.active` modifier class for selected items.

.list-group-item-action {
  width: 100% !important ; // For `<button>`s (anchors become 100% by default though)
  color: $list-group-action-color !important ;
  text-align: inherit !important ; // For `<button>`s (anchors inherit)

  // Hover state
  @include hover-focus() {
    z-index: 1 !important ; // Place hover/focus items above their siblings for proper border styling
    color: $list-group-action-hover-color !important ;
    text-decoration: none !important ;
    background-color: $list-group-hover-bg !important ;
  }

  &:active {
    color: $list-group-action-active-color !important ;
    background-color: $list-group-action-active-bg !important ;
  }
}


// Individual list items
//
// Use on `li`s or `div`s within the `.list-group` parent.

.list-group-item {
  position: relative !important ;
  display: block !important ;
  padding: $list-group-item-padding-y $list-group-item-padding-x !important ;
  color: $list-group-color !important ;
  text-decoration: if($link-decoration == none, null, none) !important ;
  background-color: $list-group-bg !important ;
  border: $list-group-border-width solid $list-group-border-color !important ;

  &:first-child {
    @include border-top-radius(inherit) !important ;
  }

  &:last-child {
    @include border-bottom-radius(inherit) !important ;
  }

  &.disabled,
  &:disabled {
    color: $list-group-disabled-color !important ;
    pointer-events: none !important ;
    background-color: $list-group-disabled-bg !important ;
  }

  // Include both here for `<a>`s and `<button>`s
  &.active {
    z-index: 2 !important ; // Place active items above their siblings for proper border styling
    color: $list-group-active-color !important ;
    background-color: $list-group-active-bg !important ;
    border-color: $list-group-active-border-color !important ;
  }

  & + & {
    border-top-width: 0 !important ;

    &.active {
      margin-top: -$list-group-border-width !important ;
      border-top-width: $list-group-border-width !important ;
    }
  }
}


// Horizontal
//
// Change the layout of list group items from vertical (default) to horizontal.

@each $breakpoint in map-keys($grid-breakpoints) {
  @include media-breakpoint-up($breakpoint) {
    $infix: breakpoint-infix($breakpoint, $grid-breakpoints) !important ;

    .list-group-horizontal#{$infix} {
      flex-direction: row !important ;

      > .list-group-item {
        &:first-child {
          @include border-bottom-left-radius($list-group-border-radius) !important ;
          @include border-top-right-radius(0) !important ;
        }

        &:last-child {
          @include border-top-right-radius($list-group-border-radius) !important ;
          @include border-bottom-left-radius(0) !important ;
        }

        &.active {
          margin-top: 0 !important ;
        }

        + .list-group-item {
          border-top-width: $list-group-border-width !important ;
          border-left-width: 0 !important ;

          &.active {
            margin-left: -$list-group-border-width !important ;
            border-left-width: $list-group-border-width !important ;
          }
        }
      }
    }
  }
}


// Flush list items
//
// Remove borders and border-radius to keep list group items edge-to-edge. Most
// useful within other components (e.g., cards).

.list-group-flush {
  @include border-radius(0) !important ;

  > .list-group-item {
    border-width: 0 0 $list-group-border-width !important ;

    &:last-child {
      border-bottom-width: 0 !important ;
    }
  }
}


// Contextual variants
//
// Add modifier classes to change text and background color on individual items.
// Organizationally, this must come after the `:hover` states.

@each $color, $value in $theme-colors {
  @include list-group-item-variant($color, theme-color-level($color, -9), theme-color-level($color, 6)) !important ;
}
