// Checkboxes and radios
//
// Base class takes care of all the key behavioral aspects.

.custom-control {
  position: relative !important ;
  z-index: 1 !important ;
  display: block !important ;
  min-height: $font-size-base * $line-height-base !important ;
  padding-left: $custom-control-gutter + $custom-control-indicator-size !important ;
  color-adjust: exact !important ; // Keep themed appearance for print
}

.custom-control-inline {
  display: inline-flex !important ;
  margin-right: $custom-control-spacer-x !important ;
}

.custom-control-input {
  position: absolute !important ;
  left: 0 !important ;
  z-index: -1 !important ; // Put the input behind the label so it doesn't overlay text
  width: $custom-control-indicator-size !important ;
  height: ($font-size-base * $line-height-base + $custom-control-indicator-size) * .5 !important ;
  opacity: 0 !important ;

  &:checked ~ .custom-control-label::before {
    color: $custom-control-indicator-checked-color !important ;
    border-color: $custom-control-indicator-checked-border-color !important ;
    @include gradient-bg($custom-control-indicator-checked-bg) !important ;
    @include box-shadow($custom-control-indicator-checked-box-shadow) !important ;
  }

  &:focus ~ .custom-control-label::before {
    // the mixin is not used here to make sure there is feedback
    @if $enable-shadows {
      box-shadow: $input-box-shadow, $custom-control-indicator-focus-box-shadow !important ;
    } @else {
      box-shadow: $custom-control-indicator-focus-box-shadow !important ;
    }
  }

  &:focus:not(:checked) ~ .custom-control-label::before {
    border-color: $custom-control-indicator-focus-border-color !important ;
  }

  &:not(:disabled):active ~ .custom-control-label::before {
    color: $custom-control-indicator-active-color !important ;
    background-color: $custom-control-indicator-active-bg !important ;
    border-color: $custom-control-indicator-active-border-color !important ;
    @include box-shadow($custom-control-indicator-active-box-shadow) !important ;
  }

  // Use [disabled] and :disabled to work around https://github.com/twbs/bootstrap/issues/28247
  &[disabled],
  &:disabled {
    ~ .custom-control-label {
      color: $custom-control-label-disabled-color !important ;

      &::before {
        background-color: $custom-control-indicator-disabled-bg !important ;
      }
    }
  }
}

// Custom control indicators
//
// Build the custom controls out of pseudo-elements.

.custom-control-label {
  position: relative !important ;
  margin-bottom: 0 !important ;
  color: $custom-control-label-color !important ;
  vertical-align: top !important ;
  cursor: $custom-control-cursor !important ;

  // Background-color and (when enabled) gradient
  &::before {
    position: absolute !important ;
    top: ($font-size-base * $line-height-base - $custom-control-indicator-size) * .5 !important ;
    left: -($custom-control-gutter + $custom-control-indicator-size) !important ;
    display: block !important ;
    width: $custom-control-indicator-size !important ;
    height: $custom-control-indicator-size !important ;
    pointer-events: none !important ;
    content: "" !important ;
    background-color: $custom-control-indicator-bg !important ;
    border: $custom-control-indicator-border-color solid $custom-control-indicator-border-width !important ;
    @include box-shadow($custom-control-indicator-box-shadow) !important ;
  }

  // Foreground (icon)
  &::after {
    position: absolute !important ;
    top: ($font-size-base * $line-height-base - $custom-control-indicator-size) * .5 !important ;
    left: -($custom-control-gutter + $custom-control-indicator-size) !important ;
    display: block !important ;
    width: $custom-control-indicator-size !important ;
    height: $custom-control-indicator-size !important ;
    content: "" !important ;
    background: 50% / #{$custom-control-indicator-bg-size} no-repeat !important ;
  }
}


// Checkboxes
//
// Tweak just a few things for checkboxes.

.custom-checkbox {
  .custom-control-label::before {
    @include border-radius($custom-checkbox-indicator-border-radius) !important ;
  }

  .custom-control-input:checked ~ .custom-control-label {
    &::after {
      background-image: escape-svg($custom-checkbox-indicator-icon-checked) !important ;
    }
  }

  .custom-control-input:indeterminate ~ .custom-control-label {
    &::before {
      border-color: $custom-checkbox-indicator-indeterminate-border-color !important ;
      @include gradient-bg($custom-checkbox-indicator-indeterminate-bg) !important ;
      @include box-shadow($custom-checkbox-indicator-indeterminate-box-shadow) !important ;
    }
    &::after {
      background-image: escape-svg($custom-checkbox-indicator-icon-indeterminate) !important ;
    }
  }

  .custom-control-input:disabled {
    &:checked ~ .custom-control-label::before {
      @include gradient-bg($custom-control-indicator-checked-disabled-bg) !important ;
    }
    &:indeterminate ~ .custom-control-label::before {
      @include gradient-bg($custom-control-indicator-checked-disabled-bg) !important ;
    }
  }
}

// Radios
//
// Tweak just a few things for radios.

.custom-radio {
  .custom-control-label::before {
    // stylelint-disable-next-line property-disallowed-list
    border-radius: $custom-radio-indicator-border-radius !important ;
  }

  .custom-control-input:checked ~ .custom-control-label {
    &::after {
      background-image: escape-svg($custom-radio-indicator-icon-checked) !important ;
    }
  }

  .custom-control-input:disabled {
    &:checked ~ .custom-control-label::before {
      @include gradient-bg($custom-control-indicator-checked-disabled-bg) !important ;
    }
  }
}


// switches
//
// Tweak a few things for switches

.custom-switch {
  padding-left: $custom-switch-width + $custom-control-gutter !important ;

  .custom-control-label {
    &::before {
      left: -($custom-switch-width + $custom-control-gutter) !important ;
      width: $custom-switch-width !important ;
      pointer-events: all !important ;
      // stylelint-disable-next-line property-disallowed-list
      border-radius: $custom-switch-indicator-border-radius !important ;
    }

    &::after {
      top: add(($font-size-base * $line-height-base - $custom-control-indicator-size) * .5, $custom-control-indicator-border-width * 2) !important ;
      left: add(-($custom-switch-width + $custom-control-gutter), $custom-control-indicator-border-width * 2) !important ;
      width: $custom-switch-indicator-size !important ;
      height: $custom-switch-indicator-size !important ;
      background-color: $custom-control-indicator-border-color !important ;
      // stylelint-disable-next-line property-disallowed-list
      border-radius: $custom-switch-indicator-border-radius !important ;
      @include transition(transform .15s ease-in-out, $custom-forms-transition) !important ;
    }
  }

  .custom-control-input:checked ~ .custom-control-label {
    &::after {
      background-color: $custom-control-indicator-bg !important ;
      transform: translateX($custom-switch-width - $custom-control-indicator-size) !important ;
    }
  }

  .custom-control-input:disabled {
    &:checked ~ .custom-control-label::before {
      @include gradient-bg($custom-control-indicator-checked-disabled-bg) !important ;
    }
  }
}


// Select
//
// Replaces the browser default select with a custom one, mostly pulled from
// https://primer.github.io/.
//

.custom-select {
  display: inline-block !important ;
  width: 100% !important ;
  height: $custom-select-height !important ;
  padding: $custom-select-padding-y ($custom-select-padding-x + $custom-select-indicator-padding) $custom-select-padding-y $custom-select-padding-x !important ;
  font-family: $custom-select-font-family !important ;
  @include font-size($custom-select-font-size) !important ;
  font-weight: $custom-select-font-weight !important ;
  line-height: $custom-select-line-height !important ;
  color: $custom-select-color !important ;
  vertical-align: middle !important ;
  background: $custom-select-bg $custom-select-background !important ;
  border: $custom-select-border-width solid $custom-select-border-color !important ;
  @include border-radius($custom-select-border-radius, 0) !important ;
  @include box-shadow($custom-select-box-shadow) !important ;
  appearance: none !important ;

  &:focus {
    border-color: $custom-select-focus-border-color !important ;
    outline: 0 !important ;
    @if $enable-shadows {
      @include box-shadow($custom-select-box-shadow, $custom-select-focus-box-shadow) !important ;
    } @else {
      // Avoid using mixin so we can pass custom focus shadow properly
      box-shadow: $custom-select-focus-box-shadow !important ;
    }

    &::-ms-value {
      // For visual consistency with other platforms/browsers,
      // suppress the default white text on blue background highlight given to
      // the selected option text when the (still closed) <select> receives focus
      // in IE and (under certain conditions) Edge.
      // See https://github.com/twbs/bootstrap/issues/19398.
      color: $input-color !important ;
      background-color: $input-bg !important ;
    }
  }

  &[multiple],
  &[size]:not([size="1"]) {
    height: auto !important ;
    padding-right: $custom-select-padding-x !important ;
    background-image: none !important ;
  }

  &:disabled {
    color: $custom-select-disabled-color !important ;
    background-color: $custom-select-disabled-bg !important ;
  }

  // Hides the default caret in IE11
  &::-ms-expand {
    display: none !important ;
  }

  // Remove outline from select box in FF
  &:-moz-focusring {
    color: transparent !important ;
    text-shadow: 0 0 0 $custom-select-color !important ;
  }
}

.custom-select-sm {
  height: $custom-select-height-sm !important ;
  padding-top: $custom-select-padding-y-sm !important ;
  padding-bottom: $custom-select-padding-y-sm !important ;
  padding-left: $custom-select-padding-x-sm !important ;
  @include font-size($custom-select-font-size-sm) !important ;
}

.custom-select-lg {
  height: $custom-select-height-lg !important ;
  padding-top: $custom-select-padding-y-lg !important ;
  padding-bottom: $custom-select-padding-y-lg !important ;
  padding-left: $custom-select-padding-x-lg !important ;
  @include font-size($custom-select-font-size-lg) !important ;
}


// File
//
// Custom file input.

.custom-file {
  position: relative !important ;
  display: inline-block !important ;
  width: 100% !important ;
  height: $custom-file-height !important ;
  margin-bottom: 0 !important ;
}

.custom-file-input {
  position: relative !important ;
  z-index: 2 !important ;
  width: 100% !important ;
  height: $custom-file-height !important ;
  margin: 0 !important ;
  overflow: hidden !important ;
  opacity: 0 !important ;

  &:focus ~ .custom-file-label {
    border-color: $custom-file-focus-border-color !important ;
    box-shadow: $custom-file-focus-box-shadow !important ;
  }

  // Use [disabled] and :disabled to work around https://github.com/twbs/bootstrap/issues/28247
  &[disabled] ~ .custom-file-label,
  &:disabled ~ .custom-file-label {
    background-color: $custom-file-disabled-bg !important ;
  }

  @each $lang, $value in $custom-file-text {
    &:lang(#{$lang}) ~ .custom-file-label::after {
      content: $value !important ;
    }
  }

  ~ .custom-file-label[data-browse]::after {
    content: attr(data-browse) !important ;
  }
}

.custom-file-label {
  position: absolute !important ;
  top: 0 !important ;
  right: 0 !important ;
  left: 0 !important ;
  z-index: 1 !important ;
  height: $custom-file-height !important ;
  padding: $custom-file-padding-y $custom-file-padding-x !important ;
  overflow: hidden !important ;
  font-family: $custom-file-font-family !important ;
  font-weight: $custom-file-font-weight !important ;
  line-height: $custom-file-line-height !important ;
  color: $custom-file-color !important ;
  background-color: $custom-file-bg !important ;
  border: $custom-file-border-width solid $custom-file-border-color !important ;
  @include border-radius($custom-file-border-radius) !important ;
  @include box-shadow($custom-file-box-shadow) !important ;

  &::after {
    position: absolute !important ;
    top: 0 !important ;
    right: 0 !important ;
    bottom: 0 !important ;
    z-index: 3 !important ;
    display: block !important ;
    height: $custom-file-height-inner !important ;
    padding: $custom-file-padding-y $custom-file-padding-x !important ;
    line-height: $custom-file-line-height !important ;
    color: $custom-file-button-color !important ;
    content: "Browse" !important ;
    @include gradient-bg($custom-file-button-bg) !important ;
    border-left: inherit !important ;
    @include border-radius(0 $custom-file-border-radius $custom-file-border-radius 0) !important ;
  }
}

// Range
//
// Style range inputs the same across browsers. Vendor-specific rules for pseudo
// elements cannot be mixed. As such, there are no shared styles for focus or
// active states on prefixed selectors.

.custom-range {
  width: 100% !important ;
  height: add($custom-range-thumb-height, $custom-range-thumb-focus-box-shadow-width * 2) !important ;
  padding: 0 !important ; // Need to reset padding
  background-color: transparent !important ;
  appearance: none !important ;

  &:focus {
    outline: 0 !important ;

    // Pseudo-elements must be split across multiple rulesets to have an effect.
    // No box-shadow() mixin for focus accessibility.
    &::-webkit-slider-thumb { box-shadow: $custom-range-thumb-focus-box-shadow !important ; }
    &::-moz-range-thumb     { box-shadow: $custom-range-thumb-focus-box-shadow !important ; }
    &::-ms-thumb            { box-shadow: $custom-range-thumb-focus-box-shadow !important ; }
  }

  &::-moz-focus-outer {
    border: 0 !important ;
  }

  &::-webkit-slider-thumb {
    width: $custom-range-thumb-width !important ;
    height: $custom-range-thumb-height !important ;
    margin-top: ($custom-range-track-height - $custom-range-thumb-height) * .5 !important ; // Webkit specific
    @include gradient-bg($custom-range-thumb-bg) !important ;
    border: $custom-range-thumb-border !important ;
    @include border-radius($custom-range-thumb-border-radius) !important ;
    @include box-shadow($custom-range-thumb-box-shadow) !important ;
    @include transition($custom-forms-transition) !important ;
    appearance: none !important ;

    &:active {
      @include gradient-bg($custom-range-thumb-active-bg) !important ;
    }
  }

  &::-webkit-slider-runnable-track {
    width: $custom-range-track-width !important ;
    height: $custom-range-track-height !important ;
    color: transparent !important ; // Why?
    cursor: $custom-range-track-cursor !important ;
    background-color: $custom-range-track-bg !important ;
    border-color: transparent !important ;
    @include border-radius($custom-range-track-border-radius) !important ;
    @include box-shadow($custom-range-track-box-shadow) !important ;
  }

  &::-moz-range-thumb {
    width: $custom-range-thumb-width !important ;
    height: $custom-range-thumb-height !important ;
    @include gradient-bg($custom-range-thumb-bg) !important ;
    border: $custom-range-thumb-border !important ;
    @include border-radius($custom-range-thumb-border-radius) !important ;
    @include box-shadow($custom-range-thumb-box-shadow) !important ;
    @include transition($custom-forms-transition) !important ;
    appearance: none !important ;

    &:active {
      @include gradient-bg($custom-range-thumb-active-bg) !important ;
    }
  }

  &::-moz-range-track {
    width: $custom-range-track-width !important ;
    height: $custom-range-track-height !important ;
    color: transparent !important ;
    cursor: $custom-range-track-cursor !important ;
    background-color: $custom-range-track-bg !important ;
    border-color: transparent !important ; // Firefox specific?
    @include border-radius($custom-range-track-border-radius) !important ;
    @include box-shadow($custom-range-track-box-shadow) !important ;
  }

  &::-ms-thumb {
    width: $custom-range-thumb-width !important ;
    height: $custom-range-thumb-height !important ;
    margin-top: 0 !important ; // Edge specific
    margin-right: $custom-range-thumb-focus-box-shadow-width !important ; // Workaround that overflowed box-shadow is hidden.
    margin-left: $custom-range-thumb-focus-box-shadow-width !important ;  // Workaround that overflowed box-shadow is hidden.
    @include gradient-bg($custom-range-thumb-bg) !important ;
    border: $custom-range-thumb-border !important ;
    @include border-radius($custom-range-thumb-border-radius) !important ;
    @include box-shadow($custom-range-thumb-box-shadow) !important ;
    @include transition($custom-forms-transition) !important ;
    appearance: none !important ;

    &:active {
      @include gradient-bg($custom-range-thumb-active-bg) !important ;
    }
  }

  &::-ms-track {
    width: $custom-range-track-width !important ;
    height: $custom-range-track-height !important ;
    color: transparent !important ;
    cursor: $custom-range-track-cursor !important ;
    background-color: transparent !important ;
    border-color: transparent !important ;
    border-width: $custom-range-thumb-height * .5 !important ;
    @include box-shadow($custom-range-track-box-shadow) !important ;
  }

  &::-ms-fill-lower {
    background-color: $custom-range-track-bg !important ;
    @include border-radius($custom-range-track-border-radius) !important ;
  }

  &::-ms-fill-upper {
    margin-right: 15px !important ; // arbitrary?
    background-color: $custom-range-track-bg !important ;
    @include border-radius($custom-range-track-border-radius) !important ;
  }

  &:disabled {
    &::-webkit-slider-thumb {
      background-color: $custom-range-thumb-disabled-bg !important ;
    }

    &::-webkit-slider-runnable-track {
      cursor: default !important ;
    }

    &::-moz-range-thumb {
      background-color: $custom-range-thumb-disabled-bg !important ;
    }

    &::-moz-range-track {
      cursor: default !important ;
    }

    &::-ms-thumb {
      background-color: $custom-range-thumb-disabled-bg !important ;
    }
  }
}

.custom-control-label::before,
.custom-file-label,
.custom-select {
  @include transition($custom-forms-transition) !important ;
}
