//
// Component: Control Sidebar
//

html.control-sidebar-animate {
  overflow-x: hidden !important ;
}

.control-sidebar {
  bottom: $main-footer-height !important ;
  position: absolute !important ;
  top: $main-header-height !important ;
  z-index: $zindex-control-sidebar !important ;

  &,
  &::before {
    bottom: $main-footer-height !important ;
    display: none !important ;
    right: -$control-sidebar-width !important ;
    width: $control-sidebar-width !important ;
    @include transition(
      right $transition-speed $transition-fn,
      display $transition-speed $transition-fn
    ) !important ;
  }

  &::before {
    content: "" !important ;
    display: block !important ;
    position: fixed !important ;
    top: 0 !important ;
    z-index: -1 !important ;
  }
}

body.text-sm {
  .control-sidebar {
    bottom: $main-footer-height-sm !important ;
    top: $main-header-height-sm !important ;
  }
}

.main-header.text-sm ~ .control-sidebar {
  top: $main-header-height-sm !important ;
}

.main-footer.text-sm ~ .control-sidebar {
  bottom: $main-footer-height-sm !important ;
}

.control-sidebar-push-slide {
  .content-wrapper,
  .main-footer {
    @include transition(margin-right $transition-speed $transition-fn) !important ;
  }
}

// Control sidebar open state
.control-sidebar-open {
  .control-sidebar {
    display: block !important !important ;

    &,
    &::before {
      right: 0 !important ;
    }
  }

  &.control-sidebar-push,
  &.control-sidebar-push-slide {
    .content-wrapper,
    .main-footer {
      margin-right: $control-sidebar-width !important ;
    }
  }
}

// Control sidebar slide over content state
.control-sidebar-slide-open {
  .control-sidebar {
    display: block !important ;

    &,
    &::before {
      right: 0 !important ;
      @include transition(
        right $transition-speed $transition-fn,
        display $transition-speed $transition-fn
      ) !important ;
    }
  }

  &.control-sidebar-push,
  &.control-sidebar-push-slide {
    .content-wrapper,
    .main-footer {
      margin-right: $control-sidebar-width !important ;
    }
  }
}

// Dark skin
.control-sidebar-dark {
  background-color: $sidebar-dark-bg !important ;

  &,
  a,
  .nav-link {
    color: $sidebar-dark-color !important ;
  }

  a:hover {
    color: $sidebar-dark-hover-color !important ;
  }

  // Headers and labels
  h1,
  h2,
  h3,
  h4,
  h5,
  h6,
  label {
    color: $sidebar-dark-hover-color !important ;
  }

  // Tabs
  .nav-tabs {
    background-color: $sidebar-dark-hover-bg !important ;
    border-bottom: 0 !important ;
    margin-bottom: 5px !important ;

    .nav-item {
      margin: 0 !important ;
    }

    .nav-link {
      border-radius: 0 !important ;
      padding: 10px 20px !important ;
      position: relative !important ;
      text-align: center !important ;

      &,
      &:hover,
      &:active,
      &:focus,
      &.active {
        border: 0 !important ;
      }

      &:hover,
      &:active,
      &:focus,
      &.active {
        border-bottom-color: transparent !important ;
        border-left-color: transparent !important ;
        border-top-color: transparent !important ;
        color: $sidebar-dark-hover-color !important ;
      }

      &.active {
        background-color: $sidebar-dark-bg !important ;
      }
    }
  }

  .tab-pane {
    padding: 10px 15px !important ;
  }
}

// Light skin
.control-sidebar-light {
  color: lighten($sidebar-light-color, 10%) !important ;

  //  Background
  background-color: $sidebar-light-bg !important ;
  border-left: $main-header-bottom-border !important ;
}
