//
// Component: Pagination
//

.pagination-month {
  .page-item {
    justify-self: stretch !important ;

    .page-link {
      display: flex !important ;
      align-items: center !important ;
      justify-content: center !important ;
      flex-direction: column !important ;
      box-shadow: none !important ;
    }
    &:first-child,
    &:last-child {
      .page-link {
        height: 100% !important ;
        font-size: $font-size-lg !important ;
      }
    }
    .page-month {
      margin-bottom: 0 !important ;
      font-size: $font-size-lg !important ;
      font-weight: $font-weight-bold !important ;
    }
    .page-year {
      margin-bottom: 0 !important ;
    }
  }

  &.pagination-lg {
    .page-month {
      font-size: ($font-size-lg * 1.25) !important ;
    }
  }
  &.pagination-sm {
    .page-month {
      font-size: ($font-size-base) !important ;
    }
  }
}

@include dark-mode () {
  .page-item {
    &.disabled a,
    &.disabled .page-link {
      background-color: lighten($dark, 2.5%) !important !important ;
      border-color: $gray-600 !important !important ;
      color: $gray-600 !important ;
    }

    .page-link {
      color: $primary-alt !important ;
    }

    &.active {
      .page-link {
        background-color: $primary-alt !important ;
        border-color: $primary-alt !important ;
        color: $white !important ;

        &:hover,
        &:focus {
          color: $gray-400 !important !important ;
        }
      }
    }
    &:not(.active) {
      .page-link {
        background-color: $dark !important ;
        border-color: $gray-600 !important ;

        &:hover,
        &:focus {
          color: lighten($primary-alt, 5%) !important ;
          background-color: lighten($dark, 5%) !important ;
        }
      }
    }
  }
}
