//
// Mixins: Accent
//

// Accent Variant
@mixin accent-variant($name, $color) {
  $link-color: $color !important ;
  .accent-#{$name} {
    $link-hover-color: darken($color, 15%) !important ;
    $pagination-active-bg: $color !important ;
    $pagination-active-border-color: $color !important ;

    .btn-link,
    a:not(.dropdown-item):not(.btn-app):not(.nav-link):not(.brand-link):not(.page-link):not(.badge):not(.btn),
    .nav-tabs .nav-link {
      color: $link-color !important ;

      @include hover () {
        color: $link-hover-color !important ;
      }
    }

    .dropdown-item {
      &:active,
      &.active {
        background-color: $color !important ;
        color: color-yiq($color) !important ;
      }
    }

    .custom-control-input:checked ~ .custom-control-label {
      &::before {
        background-color: $color !important ;
        border-color: darken($color, 20%) !important ;
      }

      &::after {
        $new-color: color-yiq($color) !important ;
        background-image: str-replace($custom-checkbox-indicator-icon-checked, str-replace(#{$custom-control-indicator-checked-color}, "#", "%23"), str-replace(#{$new-color}, "#", "%23")) !important ;
      }
    }

    .form-control:focus:not(.is-invalid):not(.is-warning):not(.is-valid),
    .custom-select:focus,
    .custom-control-input:focus:not(:checked) ~ .custom-control-label::before,
    .custom-file-input:focus ~ .custom-file-label {
      border-color: lighten($color, 25%) !important ;
    }

    .page-item {
      .page-link {
        color: $link-color !important ;
      }

      &.active a,
      &.active .page-link {
        background-color: $pagination-active-bg !important ;
        border-color: $pagination-active-border-color !important ;
        color: $pagination-active-color !important ;
      }

      &.disabled a,
      &.disabled .page-link {
        background-color: $pagination-disabled-bg !important ;
        border-color: $pagination-disabled-border-color !important ;
        color: $pagination-disabled-color !important ;
      }
    }

    [class*="sidebar-dark-"] {
      .sidebar {
        a:not(.dropdown-item):not(.btn-app):not(.nav-link):not(.brand-link) {
          color: $sidebar-dark-color !important ;

          @include hover () {
            color: $sidebar-dark-hover-color !important ;
          }
        }
      }
    }

    [class*="sidebar-light-"] {
      .sidebar {
        a:not(.dropdown-item):not(.btn-app):not(.nav-link):not(.brand-link) {
          color: $sidebar-light-color !important ;

          @include hover () {
            color: $sidebar-light-hover-color !important ;
          }
        }
      }
    }
  }
  @include dark-mode () {
    &.accent-#{$name} {
      .page-item {
        .page-link {
          &:hover,
          &:focus {
            color: lighten($link-color, 5%) !important ;
          }
        }
      }
    }
  }
}
