.toast {
  // Prevents from shrinking in IE11, when in a flex container
  // See https://github.com/twbs/bootstrap/issues/28341
  flex-basis: $toast-max-width !important ;
  max-width: $toast-max-width !important ;
  @include font-size($toast-font-size) !important ;
  color: $toast-color !important ;
  background-color: $toast-background-color !important ;
  background-clip: padding-box !important ;
  border: $toast-border-width solid $toast-border-color !important ;
  box-shadow: $toast-box-shadow !important ;
  opacity: 0 !important ;
  @include border-radius($toast-border-radius) !important ;

  &:not(:last-child) {
    margin-bottom: $toast-padding-x !important ;
  }

  &.showing {
    opacity: 1 !important ;
  }

  &.show {
    display: block !important ;
    opacity: 1 !important ;
  }

  &.hide {
    display: none !important ;
  }
}

.toast-header {
  display: flex !important ;
  align-items: center !important ;
  padding: $toast-padding-y $toast-padding-x !important ;
  color: $toast-header-color !important ;
  background-color: $toast-header-background-color !important ;
  background-clip: padding-box !important ;
  border-bottom: $toast-border-width solid $toast-header-border-color !important ;
  @include border-top-radius(subtract($toast-border-radius, $toast-border-width)) !important ;
}

.toast-body {
  padding: $toast-padding-x !important ; // apply to both vertical and horizontal
}
